class Solution:
    def matrixSum(self, nums: List[List[int]]) -> int:
        # Sort each row in descending order
        for row in nums:
            row.sort(reverse=True)

        score = 0
        # For each column (since we remove largest from each row), find the maximum value
        # across all rows in that column position
        for col in range(len(nums[0])):
            max_val = 0
            for row in nums:
                if col < len(row):
                    max_val = max(max_val, row[col])
            score += max_val

        return score

class Solution:
    def maximumOr(self, nums: List[int], k: int) -> int:
        n = len(nums)
        max_or = 0

        # Try applying all k operations to each element
        for i in range(n):
            # Compute the OR value when we apply k operations to nums[i]
            new_val = nums[i] * (1 << k)

            # Compute the OR of the array with nums[i] replaced by new_val
            # We can avoid building the full array by computing OR efficiently
            current_or = 0
            for j in range(n):
                if j == i:
                    current_or |= new_val
                else:
                    current_or |= nums[j]

            max_or = max(max_or, current_or)

        return max_or

