class Solution:
    def minExtraChar(self, s: str, dictionary: List[str]) -> int:
        dictionary_set = set(dictionary)
        n = len(s)
        # dp[i] represents the minimum extra characters for s[0:i]
        dp = [0] * (n + 1)

        for i in range(1, n + 1):
            # Default: we don't use any word ending at i, so extra characters = i
            dp[i] = dp[i-1] + 1

            # Try to match a word ending at position i
            for j in range(i):
                # Check if s[j:i] is in dictionary
                substring = s[j:i]
                if substring in dictionary_set:
                    dp[i] = min(dp[i], dp[j])

        return dp[n]

