class Solution:
    def longestSemiRepetitiveSubstring(self, s: str) -> int:
        n = len(s)
        max_len = 0
        left = 0
        repeated_count = 0
        last_repeated_char = None

        for right in range(n):
            if right > 0 and s[right] == s[right - 1]:
                if repeated_count == 0:
                    repeated_count = 1
                    last_repeated_char = s[right]
                else:
                    # More than one consecutive pair found
                    while left < right:
                        if s[left] == s[left + 1]:
                            left += 1
                            if left == right:
                                break
                        elif left < right and s[left] == s[right]:
                            # Need to skip until we find a different character
                            break
                        else:
                            left += 1
                    # Reset the window
                    repeated_count = 1
                    last_repeated_char = s[right]

            # Check if current window is valid
            if repeated_count <= 1:
                max_len = max(max_len, right - left + 1)

        return max_len

