class Solution:
    def circularGameLosers(self, n: int, k: int) -> List[int]:
        visited = [False] * (n + 1)
        current = 1
        visited[current] = True

        turn = 1
        while True:
            next_pos = (current + turn * k - 1) % n + 1
            if visited[next_pos]:
                break
            visited[next_pos] = True
            current = next_pos
            turn += 1

        losers = []
        for i in range(1, n + 1):
            if not visited[i]:
                losers.append(i)

        return losers

class Solution:
    def minLength(self, s: str) -> int:
        stack = []
        for char in s:
            if stack and stack[-1] == 'A' and char == 'B':
                stack.pop()
            elif stack and stack[-1] == 'C' and char == 'D':
                stack.pop()
            else:
                stack.append(char)
        return len(stack)

class Solution:
    def punishmentNumber(self, n: int) -> int:
        def can_partition(s, target):
            if s == "":
                return target == 0
            if target == 0:
                return s == ""

            # Try to partition starting from the first digit
            for i in range(1, len(s) + 1):
                prefix = s[:i]
                if prefix[0] == '0' and len(prefix) > 1:
                    continue  # Skip invalid numbers with leading zeros
                prefix_val = int(prefix)
                if prefix_val > target:
                    continue
                if can_partition(s[i:], target - prefix_val):
                    return True
            return False

        result = 0
        for i in range(1, n + 1):
            square = i * i
            if can_partition(str(square), i):
                result += square

        return result

