class Solution:
    def smallestString(self, s: str) -> str:
        # Convert string to list for easy manipulation
        chars = list(s)
        n = len(s)

        # If the string is all 'a', applying operation would make it 'z' which is lexicographically larger
        # So we return the original string
        if all(c == 'a' for c in s):
            return s

        # Find the first non-'a' character
        start = 0
        while start < n and chars[start] == 'a':
            start += 1

        # Apply operation from start until we hit 'a'
        i = start
        while i < n and chars[i] != 'a':
            chars[i] = chr(ord(chars[i]) - 1)
            i += 1

        return ''.join(chars)

