class Solution:
    def countBeautifulPairs(self, nums: List[int]) -> int:
        from math import gcd

        def first_digit(n):
            return int(str(n)[0])

        def last_digit(n):
            return int(str(n)[-1])

        count = 0
        n = len(nums)

        for i in range(n):
            for j in range(i + 1, n):
                first = first_digit(nums[i])
                last = last_digit(nums[j])
                if gcd(first, last) == 1:
                    count += 1

        return count

class Solution:
    def longestEqualSubarray(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if n == 0:
            return 0

        max_length = 1

        # Group indices by value
        value_to_indices = {}
        for i, val in enumerate(nums):
            if val not in value_to_indices:
                value_to_indices[val] = []
            value_to_indices[val].append(i)

        # For each value, we want to find the longest subarray where we can delete at most k elements
        # to make all elements equal to that value

        for val, indices in value_to_indices.items():
            if not indices:
                continue

            # Use sliding window on indices to find longest subarray where we can delete at most k elements
            left = 0
            max_in_this_value = 1

            for right in range(len(indices)):
                # The window is from indices[left] to indices[right]
                # The number of elements not equal to val in this window is:
                # (indices[right] - indices[left] + 1) - (right - left + 1)
                # = (indices[right] - indices[left]) - (right - left)
                # We need this to be <= k

                while left <= right and (indices[right] - indices[left]) - (right - left) > k:
                    left += 1

                # The number of elements equal to val in the current window is (right - left + 1)
                max_in_this_value = max(max_in_this_value, right - left + 1)

        return max_in_this_value

