class Solution:
    def relocateMarbles(self, nums: List[int], moveFrom: List[int], moveTo: List[int]) -> List[int]:
        # Use a set to track occupied positions
        positions = set(nums)

        # Apply each move step by step
        for i in range(len(moveFrom)):
            from_pos = moveFrom[i]
            to_pos = moveTo[i]

            # If there are marbles at from_pos, remove them and add to to_pos
            if from_pos in positions:
                positions.remove(from_pos)
                positions.add(to_pos)

        # Return sorted list of occupied positions
        return sorted(positions)

class Solution:
    def sumOfSquares(self, nums: List[int]) -> int:
        n = len(nums)
        total = 0
        for i in range(1, n + 1):
            if n % i == 0:
                total += nums[i - 1] * nums[i - 1]
        return total

class Solution:
    def findValueOfPartition(self, nums: List[int]) -> int:
        nums.sort()
        min_diff = float('inf')
        for i in range(len(nums) - 1):
            min_diff = min(min_diff, nums[i + 1] - nums[i])
        return min_diff

class Solution:
    def maximumNumberOfStringPairs(self, words: List[str]) -> int:
        word_set = set()
        pairs = 0

        for word in words:
            reversed_word = word[::-1]
            if reversed_word in word_set:
                pairs += 1
                word_set.remove(reversed_word)
            else:
                word_set.add(word)

        return pairs

class Solution:
    def specialPerm(self, nums: List[int]) -> int:
        n = len(nums)
        MOD = 10**9 + 7

        # Precompute divisibility relationships
        # For each pair (i, j), check if nums[i] % nums[j] == 0 or nums[j] % nums[i] == 0
        def can_place(prev, curr):
            return prev % curr == 0 or curr % prev == 0

        # Use bitmask DP: dp[mask][last] = number of valid permutations using nums in mask with last element as nums[last]
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(mask, last_idx):
            # mask represents which elements have been used
            # last_idx is the index of the last element placed

            # All elements are used
            if mask == (1 << n) - 1:
                return 1

            result = 0
            for i in range(n):
                if mask & (1 << i):
                    continue

                # Check if we can place nums[i] after the last element
                if last_idx == -1:  # First element
                    result = (result + dp(mask | (1 << i), i)) % MOD
                else:
                    if can_place(nums[last_idx], nums[i]):
                        result = (result + dp(mask | (1 << i), i)) % MOD

            return result

        return dp(0, -1)

class Solution:
    def sumImbalanceNumbers(self, nums: List[int]) -> int:
        n = len(nums)
        total_imbalance = 0

        # Iterate over all possible subarrays
        for i in range(n):
            for j in range(i, n):
                # Extract subarray from i to j
                subarray = nums[i:j+1]
                # Sort the subarray to compute imbalance
                sorted_subarray = sorted(subarray)
                # Count imbalance: number of adjacent pairs with difference > 1
                imbalance = 0
                for k in range(len(sorted_subarray) - 1):
                    if sorted_subarray[k+1] - sorted_subarray[k] > 1:
                        imbalance += 1
                total_imbalance += imbalance

        return total_imbalance

