class Solution:
    def minimizeConcatenatedLength(self, words: List[str]) -> int:
        n = len(words)
        if n == 1:
            return len(words[0])

        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(i, first, last):
            if i == n:
                return 0

            # Option 1: append current word to the end
            # join(current_string, words[i])
            new_first = first
            new_last = words[i][-1]
            append_len = len(words[i])
            if last == words[i][0]:
                append_len -= 1
            option1 = append_len + dp(i + 1, new_first, new_last)

            # Option 2: prepend current word to the beginning
            # join(words[i], current_string)
            new_first = words[i][0]
            new_last = last
            prepend_len = len(words[i])
            if words[i][-1] == first:
                prepend_len -= 1
            option2 = prepend_len + dp(i + 1, new_first, new_last)

            return min(option1, option2)

        # Start with first word
        first_char = words[0][0]
        last_char = words[0][-1]

        # Total length = length of first word + minimum additional length from joins
        # The DP function computes the total length added by joining the rest of the words
        # So we return len(words[0]) + dp(1, first_char, last_char)

        return len(words[0]) + dp(1, first_char, last_char)

class Solution:
    def maximumJumps(self, nums: List[int], target: int) -> int:
        n = len(nums)
        # dp[i] represents the maximum number of jumps to reach index i
        dp = [-1] * n
        dp[0] = 0  # We start at index 0 with 0 jumps

        for i in range(1, n):
            for j in range(i):
                # Check if we can jump from index j to index i
                diff = nums[i] - nums[j]
                if abs(diff) <= target and dp[j] != -1:
                    if dp[i] == -1:
                        dp[i] = dp[j] + 1
                    else:
                        dp[i] = max(dp[i], dp[j] + 1)

        return dp[n-1]

class Solution:
    def countCompleteSubarrays(self, nums: List[int]) -> int:
        distinct_nums = len(set(nums))
        n = len(nums)
        count = 0

        # Check every possible subarray
        for i in range(n):
            seen = set()
            for j in range(i, n):
                seen.add(nums[j])
                # If we have collected all distinct elements, then this subarray is complete
                if len(seen) == distinct_nums:
                    count += 1

        return count

class Solution:
    def longestAlternatingSubarray(self, nums: List[int], threshold: int) -> int:
        max_length = 0
        n = len(nums)

        for i in range(n):
            # Check if current element is even and within threshold
            if nums[i] % 2 == 0 and nums[i] <= threshold:
                length = 1
                # Extend the subarray as long as conditions are satisfied
                for j in range(i + 1, n):
                    # Check if next element has alternating parity and is within threshold
                    if nums[j] <= threshold and (nums[j] % 2 != nums[j-1] % 2):
                        length += 1
                    else:
                        break
                max_length = max(max_length, length)

        return max_length

class Solution:
    def numberOfGoodSubarraySplits(self, nums: List[int]) -> int:
        MOD = 10**9 + 7

        # Find all positions of 1s
        ones = []
        for i, num in enumerate(nums):
            if num == 1:
                ones.append(i)

        # If no 1s found, return 0 (but problem guarantees at least one 1)
        if not ones:
            return 0

        # If only one 1, there's only one way to split (the entire array)
        if len(ones) == 1:
            return 1

        # For multiple 1s, we need to count the ways to split between consecutive 1s
        # Between two consecutive 1s at positions ones[i] and ones[i+1], 
        # we can choose any position between them to split, which gives (ones[i+1] - ones[i]) choices
        result = 1
        for i in range(len(ones) - 1):
            gap = ones[i + 1] - ones[i]
            result = (result * gap) % MOD

        return result

class Solution:
    def continuousSubarrays(self, nums: List[int]) -> int:
        from collections import deque

        n = len(nums)
        result = 0

        # Use sliding window with two deques to track min and max
        min_deque = deque()  # stores indices of elements in increasing order
        max_deque = deque()  # stores indices of elements in decreasing order

        left = 0

        for right in range(n):
            # Remove elements out of the valid range (difference > 2)
            while abs(nums[right] - nums[min_deque[0]]) > 2 or abs(nums[right] - nums[max_deque[0]]) > 2:
                # Shrink window from left
                while left <= right and (min_deque and min_deque[0] == left or max_deque and max_deque[0] == left):
                    if min_deque and min_deque[0] == left:
                        min_deque.popleft()
                    if max_deque and max_deque[0] == left:
                        max_deque.popleft()
                    left += 1

            # Add current element to min and max deques
            while min_deque and nums[min_deque[-1]] >= nums[right]:
                min_deque.pop()
            min_deque.append(right)

            while max_deque and nums[max_deque[-1]] <= nums[right]:
                max_deque.pop()
            max_deque.append(right)

            # All subarrays ending at right and starting from left to right are valid
            result += right - left + 1

        return result

class Solution:
    def maxNonDecreasingLength(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)
        # dp[i][0] = length of longest non-decreasing subarray ending at i using nums1[i]
        # dp[i][1] = length of longest non-decreasing subarray ending at i using nums2[i]
        dp = [[0, 0] for _ in range(n)]
        max_len = 0

        for i in range(n):
            # Try nums1[i]
            if i == 0:
                dp[i][0] = 1
            else:
                # Check if nums1[i] >= previous nums1[i-1] or nums2[i-1]
                if nums1[i] >= nums1[i-1]:
                    dp[i][0] = dp[i-1][0] + 1
                if nums1[i] >= nums2[i-1]:
                    dp[i][0] = max(dp[i][0], dp[i-1][1] + 1)

            # Try nums2[i]
            if i == 0:
                dp[i][1] = 1
            else:
                # Check if nums2[i] >= previous nums1[i-1] or nums2[i-1]
                if nums2[i] >= nums1[i-1]:
                    dp[i][1] = dp[i-1][0] + 1
                if nums2[i] >= nums2[i-1]:
                    dp[i][1] = max(dp[i][1], dp[i-1][1] + 1)

            max_len = max(max_len, dp[i][0], dp[i][1])

        return max_len

