class Solution:
    def minimumString(self, a: str, b: str, c: str) -> str:
        def merge(s1, s2):
            # Try to merge s1 and s2 by checking if suffix of s1 matches prefix of s2
            i = len(s1) - 1
            j = 0
            while i >= 0 and j < len(s2):
                if s1[i] == s2[j]:
                    i -= 1
                    j += 1
                else:
                    break
            # If we found overlap, merge with overlap
            if j > 0:
                return s1 + s2[j:]
            else:
                return s1 + s2

        def contains_all(s, strings):
            for string in strings:
                if string not in s:
                    return False
            return True

        # Try all permutations of the three strings
        candidates = []
        perms = [
            [a, b, c],
            [a, c, b],
            [b, a, c],
            [b, c, a],
            [c, a, b],
            [c, b, a]
        ]

        for perm in perms:
            merged = perm[0]
            for i in range(1, 3):
                merged = merge(merged, perm[i])
            candidates.append(merged)

        # Filter candidates that contain all three strings
        valid_candidates = []
        for cand in candidates:
            if contains_all(cand, [a, b, c]):
                valid_candidates.append(cand)

        # Return the one with minimum length, then lexicographically smallest
        if not valid_candidates:
            return a + b + c

        valid_candidates.sort(key=lambda x: (len(x), x))
        return valid_candidates[0]

