class Solution:
    def checkArray(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        # Use difference array to track the effect of operations
        diff = [0] * (n + 1)

        for i in range(n):
            # The current value should be the original value minus the total decrease from operations
            current_val = nums[i] - diff[i]

            # If the current value is negative, it's impossible
            if current_val < 0:
                return False

            # We need to decrease the next k elements by 1 (if possible)
            # The number of operations that affect index i is exactly current_val
            # So we need to subtract current_val from the next k elements
            if i + k < n:
                diff[i + k] += current_val
            else:
                # If we go beyond the array, we can't decrease beyond the array
                # But we must have current_val == 0 since we can't decrease beyond
                if current_val > 0:
                    return False

        # After processing all elements, we need to verify that all values are reduced to 0
        # We do this by checking that at each index, the cumulative decrease equals the original value
        current_decrease = 0
        for i in range(n):
            current_decrease += diff[i]
            # The actual value at index i should be nums[i] - current_decrease
            if nums[i] < current_decrease:
                return False

        return True

