class Solution:
    def minimumChanges(self, s: str, k: int) -> int:
        n = len(s)

        # Precompute cost to make a substring into a semi-palindrome
        def get_cost(substring):
            if len(substring) <= 2:
                return 0

            min_changes = float('inf')
            length = len(substring)

            # Try all possible divisors d where 1 <= d < length and length % d == 0
            for d in range(1, length):
                if length % d == 0:
                    # Group indices by modulo d
                    groups = [[] for _ in range(d)]
                    for i in range(length):
                        groups[i % d].append(substring[i])

                    # For each group, make it a palindrome
                    changes = 0
                    for group in groups:
                        if len(group) == 0:
                            continue
                        # Make group a palindrome
                        group_len = len(group)
                        for i in range(group_len // 2):
                            if group[i] != group[group_len - 1 - i]:
                                changes += 1
                    min_changes = min(min_changes, changes)

            return min_changes if min_changes != float('inf') else 0

        # DP: dp[i][j] = minimum changes to partition s[0:i] into j substrings
        # We'll use a different approach: try all possible partitions

        # Precompute cost for every substring
        cost = []
        for i in range(n):
            substr = s[i:]
            c = get_cost(substr)
            cost.append(c)

        # Actually, we need to compute cost for every substring of length l
        # Let's recompute properly
        cost_table = {}

        def compute_cost(start, end):
            substr = s[start:end+1]
            if len(substr) <= 2:
                return 0
            min_changes = float('inf')
            length = len(substr)
            for d in range(1, length):
                if length % d == 0:
                    groups = [[] for _ in range(d)]
                    for i in range(length):
                        groups[i % d].append(substr[i])
                    changes = 0
                    for group in groups:
                        if len(group) == 0:
                            continue
                        for j in range(len(group) // 2):
                            if group[j] != group[len(group) - 1 - j]:
                                changes += 1
                    min_changes = min(min_changes, changes)
            return min_changes if min_changes != float('inf') else 0

        # DP: dp[i][j] = min cost to partition s[0:i] into j parts
        # i is end index (0-indexed), j is number of parts
        dp = [[float('inf')] * (k + 1) for _ in range(n + 1)]

        # Base case: 0 characters, 0 parts
        dp[0][0] = 0

        for i in range(1, n + 1):
            for j in range(1, min(k, i) + 1):
                # Try all possible last substring starting at pos
                for start in range(i):
                    # Last substring is from start to i-1
                    if start == 0:
                        # First substring
                        cost_val = compute_cost(0, i-1)
                        dp[i][j] = min(dp[i][j], cost_val)
                    else:
                        # Partition s[0:start] into j-1 parts
                        if dp[start][j-1] != float('inf'):
                            cost_val = compute_cost(start, i-1)
                            dp[i][j] = min(dp[i][j], dp[start][j-1] + cost_val)

        return dp[n][k]

