class Solution:
    def minimumBeautifulSubstrings(self, s: str) -> int:
        # Powers of 5 up to 2^15 (since max string length is 15)
        powers_of_5 = []
        power = 1
        while power <= (1 << 15):
            powers_of_5.append(bin(power)[2:])
            power *= 5

        # Memoization for DP
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(idx):
            if idx == len(s):
                return 0

            # Try all possible substrings starting at idx
            min_parts = float('inf')

            # Check if we can form a beautiful substring from idx
            for end in range(idx + 1, len(s) + 1):
                substr = s[idx:end]

                # Skip if it has leading zeros (except single '0' which is invalid anyway)
                if substr[0] == '0' and len(substr) > 1:
                    continue

                # Check if this substring is a power of 5 in binary
                if substr in powers_of_5:
                    rest_parts = dp(end) if end < len(s) else 0
                    min_parts = min(min_parts, 1 + rest_parts)

            return min_parts if min_parts != float('inf') else -1

        result = dp(0)
        return result if result != float('inf') else -1

