class Solution:
    def minimumIndex(self, nums: List[int]) -> int:
        n = len(nums)
        # Count frequency of each element
        freq = {}
        for num in nums:
            freq[num] = freq.get(num, 0) + 1

        # Find the dominant element (it's the only one with freq * 2 > n)
        dominant = None
        for num, count in freq.items():
            if count * 2 > n:
                dominant = num
                break

        # Count how many times dominant appears in prefix arrays
        prefix_count = 0
        dominant_count = freq[dominant]

        # Try each possible split index
        for i in range(n - 1):
            # Update prefix count of dominant element
            if nums[i] == dominant:
                prefix_count += 1

            # Left array: [0, i], right array: [i+1, n-1]
            left_len = i + 1
            right_len = n - 1 - i

            # Check if dominant is dominant in both parts
            left_freq = prefix_count
            right_freq = dominant_count - prefix_count

            # Check dominant condition for left array
            if left_freq * 2 > left_len:
                # Check dominant condition for right array
                if right_freq * 2 > right_len:
                    return i

        return -1

