    def isGood(self, nums: List[int]) -> bool:
        n = max(nums)
        expected_length = n + 1

        # Check if the length matches
        if len(nums) != expected_length:
            return False

        # Count frequency of each number
        from collections import Counter
        count = Counter(nums)

        # Check if all numbers from 1 to n-1 appear exactly once
        for i in range(1, n):
            if count[i] != 1:
                return False

        # Check if number n appears exactly twice
        if count[n] != 2:
            return False

        return True

class Solution:
    def maxSum(self, nums: List[int]) -> int:
        def max_digit(n):
            return max(int(d) for d in str(n))

        # Group numbers by their maximum digit
        digit_groups = {}

        for num in nums:
            max_d = max_digit(num)
            if max_d not in digit_groups:
                digit_groups[max_d] = []
            digit_groups[max_d].append(num)

        # Find the maximum sum among pairs with equal maximum digits
        max_pair_sum = -1

        for max_d, group in digit_groups.items():
            if len(group) >= 2:
                # Sort in descending order to get maximum sum
                group.sort(reverse=True)
                # Sum the two largest numbers in the group
                pair_sum = group[0] + group[1]
                max_pair_sum = max(max_pair_sum, pair_sum)

        return max_pair_sum

class Solution:
    def canSplitArray(self, nums: List[int], m: int) -> bool:
        n = len(nums)
        # If array has length 1 or 2, we can always split it (since we need n arrays)
        if n <= 2:
            return True

        # Use dynamic programming to check if we can split the array
        # dp[i][j] represents whether we can split the subarray nums[i:j+1] into individual elements
        dp = [[False] * n for _ in range(n)]

        # Every single element can be split (trivially)
        for i in range(n):
            dp[i][i] = True

        # For subarrays of length 2, we can split if sum >= m
        for i in range(n - 1):
            if nums[i] + nums[i + 1] >= m:
                dp[i][i + 1] = True

        # Fill the DP table for longer subarrays
        for length in range(3, n + 1):
            for i in range(n - length + 1):
                j = i + length - 1
                # Try all possible splits
                for k in range(i, j):
                    # Check if we can split at position k
                    if dp[i][k] and dp[k + 1][j]:
                        dp[i][j] = True
                        break

        return dp[0][n - 1]

