class Solution:
    def countSymmetricIntegers(self, low: int, high: int) -> int:
        def is_symmetric(n):
            s = str(n)
            if len(s) % 2 != 0:
                return False
            n_digits = len(s) // 2
            first_half = s[:n_digits]
            second_half = s[n_digits:]
            return sum(int(d) for d in first_half) == sum(int(d) for d in second_half)

        count = 0
        for i in range(low, high + 1):
            if is_symmetric(i):
                count += 1
        return count

class Solution:
    def minAbsoluteDifference(self, nums: List[int], x: int) -> int:
        n = len(nums)
        min_diff = float('inf')

        # For each valid starting index i, we look at indices j where j >= i + x
        # or j <= i - x
        for i in range(n):
            for j in range(n):
                if abs(i - j) >= x:
                    min_diff = min(min_diff, abs(nums[i] - nums[j]))

        return min_diff

