    def numberOfBeautifulIntegers(self, low: int, high: int, k: int) -> int:
        def count_beautiful(n):
            if n < 10:
                return 0

            # Convert number to string to work with digits
            s = str(n)
            len_s = len(s)

            # Use digit DP to count beautiful numbers <= n
            from functools import lru_cache

            @lru_cache(maxsize=None)
            def dp(pos, tight, even_count, odd_count, started):
                # pos: current position in digit string
                # tight: whether we are still bounded by the original number
                # even_count: count of even digits so far
                # odd_count: count of odd digits so far
                # started: whether we have started (to avoid leading zeros)

                if pos == len_s:
                    return 1 if even_count == odd_count and even_count > 0 else 0

                result = 0
                limit = int(s[pos]) if tight else 9

                for digit in range(limit + 1):
                    new_tight = tight and (digit == limit)
                    new_started = started or (digit > 0)

                    # Skip if we haven't started and digit is 0 (leading zero)
                    if not new_started and digit == 0:
                        result += dp(pos + 1, new_tight, even_count, odd_count, False)
                    else:
                        new_even = even_count
                        new_odd = odd_count
                        if digit % 2 == 0:
                            new_even += 1
                        else:
                            new_odd += 1

                        result += dp(pos + 1, new_tight, new_even, new_odd, True)

                return result

            return dp(0, True, 0, 0, False)

        # Count beautiful numbers in [0, high] minus [0, low-1]
        return count_beautiful(high) - count_beautiful(low - 1)

