        j = 0
        for i in range(len(str1)):
            # Check if str1[i] can become str2[j] by incrementing
            char1 = str1[i]
            char2 = str2[j]

            # Case 1: Direct match
            if char1 == char2:
                j += 1
                if j == len(str2):
                    return True

            # Case 2: Incrementing char1 gives char2
            # Convert to numbers: a=0, b=1, ..., z=25
            # Incrementing char1 should give char2
            char1_val = ord(char1) - ord('a')
            char2_val = ord(char2) - ord('a')

            # Check if incrementing char1 gives char2
            if (char1_val + 1) % 26 == char2_val:
                j += 1
                if j == len(str2):
                    return True

        return False

class Solution:
    def furthestDistanceFromOrigin(self, moves: str) -> int:
        left_count = 0
        right_count = 0
        underscore_count = 0

        for move in moves:
            if move == 'L':
                left_count += 1
            elif move == 'R':
                right_count += 1
            else:  # move is '_'
                underscore_count += 1

        # We can choose to go left or right for each underscore
        # To maximize distance from origin, we go all the way in one direction
        # So the furthest distance is the sum of one direction and the underscores
        # If we go left, distance = left_count + underscore_count
        # If we go right, distance = right_count + underscore_count
        # We want the maximum distance, so we take the maximum of these two
        return max(left_count + underscore_count, right_count + underscore_count)

