class Solution:
    def numberOfPoints(self, nums: List[List[int]]) -> int:
        # Extract all start and end points
        intervals = nums

        # Create a set to store all covered integer points
        covered = set()

        # For each interval, add all integer points from start to end (inclusive)
        for start, end in intervals:
            for point in range(start, end + 1):
                covered.add(point)

        # Return the size of the covered set
        return len(covered)

class Solution:
    def minOperations(self, nums: List[int], k: int) -> int:
        collection = set()
        operations = 0

        # Process elements from the end of the array
        for i in range(len(nums) - 1, -1, -1):
            operations += 1
            element = nums[i]
            if element <= k:
                collection.add(element)

            # Check if we have collected all elements from 1 to k
            if len(collection) == k:
                return operations

        return operations

class Solution:
    def sumIndicesWithKSetBits(self, nums: List[int], k: int) -> int:
        def count_set_bits(n):
            count = 0
            while n:
                count += n & 1
                n >>= 1
            return count

        total = 0
        for i in range(len(nums)):
            if count_set_bits(i) == k:
                total += nums[i]
        return total

class Solution:
    def lengthOfLongestSubsequence(self, nums: List[int], target: int) -> int:
        n = len(nums)
        # dp[i] represents the maximum length of subsequence that sums to i
        dp = [-1] * (target + 1)
        dp[0] = 0  # empty subsequence sums to 0 with length 0

        for num in nums:
            # Traverse backwards to avoid using updated values in same iteration
            for curr_sum in range(target, num - 1, -1):
                if dp[curr_sum - num] != -1:
                    dp[curr_sum] = max(dp[curr_sum], dp[curr_sum - num] + 1)

        return dp[target]

class Solution:
    def minSizeSubarray(self, nums: List[int], target: int) -> int:
        n = len(nums)
        total_sum = sum(nums)

        # If target is greater than total_sum, we can use complete copies of nums
        # to reach the target, and then find the minimal subarray for the remainder
        if target > total_sum:
            # We need at least target // total_sum complete copies of nums
            # Then we need to find the minimal subarray in one cycle that sums to target % total_sum
            remainder = target % total_sum
            if remainder == 0:
                return target // total_sum
            else:
                # Find minimal subarray sum in nums that equals remainder
                min_len = float('inf')
                prefix_sum = 0
                prefix = [0]
                for num in nums:
                    prefix_sum += num
                    prefix.append(prefix_sum)

                # Use two pointers to find minimal length subarray with sum = remainder
                for i in range(n):
                    for j in range(i, n):
                        if prefix[j+1] - prefix[i] == remainder:
                            min_len = min(min_len, j - i + 1)

                return (target // total_sum) + (min_len if min_len != float('inf') else -1)

        # If target <= total_sum, we can find a subarray in one cycle
        # or use a combination of complete cycles and partial cycles
        # But since target <= total_sum, we only need to find a subarray in one cycle
        min_len = float('inf')
        prefix_sum = 0
        prefix = [0]
        for num in nums:
            prefix_sum += num
            prefix.append(prefix_sum)

        # Check all possible subarrays in one cycle
        for i in range(n):
            for j in range(i, n):
                if prefix[j+1] - prefix[i] == target:
                    min_len = min(min_len, j - i + 1)

        return min_len if min_len != float('inf') else -1

