class Solution:
    def shortestBeautifulSubstring(self, s: str, k: int) -> str:
        n = len(s)
        beautiful_substrings = []

        # Find all substrings with exactly k ones
        for i in range(n):
            ones = 0
            for j in range(i, n):
                if s[j] == '1':
                    ones += 1
                if ones == k:
                    beautiful_substrings.append(s[i:j+1])

        # If no beautiful substring found, return empty string
        if not beautiful_substrings:
            return ""

        # Find the shortest length
        min_len = min(len(sub) for sub in beautiful_substrings)

        # Filter substrings with minimum length and return lexicographically smallest
        candidates = [sub for sub in beautiful_substrings if len(sub) == min_len]
        candidates.sort()  # Lexicographic order

        return candidates[0]

class Solution:
    def maximumTripletValue(self, nums: List[int]) -> int:
        n = len(nums)
        max_value = 0

        for i in range(n):
            for j in range(i + 1, n):
                for k in range(j + 1, n):
                    value = (nums[i] - nums[j]) * nums[k]
                    max_value = max(max_value, value)

        return max_value

class Solution:
    def sumCounts(self, nums: List[int]) -> int:
        n = len(nums)
        total = 0

        # Iterate through all possible subarrays
        for i in range(n):
            distinct = set()
            for j in range(i, n):
                distinct.add(nums[j])
                total += len(distinct) ** 2

        return total

class Solution:
    def lastVisitedIntegers(self, words: List[str]) -> List[int]:
        nums = []
        result = []
        consecutive_prev = 0

        for word in words:
            if word == "prev":
                consecutive_prev += 1
                # If we have visited integers, get the (consecutive_prev - 1)th from the end
                if consecutive_prev <= len(nums):
                    result.append(nums[-consecutive_prev])
                else:
                    result.append(-1)
            else:
                # It's a number string, add to nums and reset consecutive prev counter
                nums.append(int(word))
                consecutive_prev = 0

        return result

