    def minSum(self, nums1: List[int], nums2: List[int]) -> int:
        sum1 = sum(nums1)
        sum2 = sum(nums2)

        zeros1 = nums1.count(0)
        zeros2 = nums2.count(0)

        # If there are no zeros in either array, we need to check if sums are already equal
        # Otherwise, we can always increase the smaller sum by replacing zeros with minimum positive values

        # If nums1 has zeros, we can make sum1 at least sum1 + 1 (by replacing 0 with 1)
        # If nums2 has zeros, we can make sum2 at least sum2 + 1

        min_sum1 = sum1 if zeros1 == 0 else sum1 + 1
        min_sum2 = sum2 if zeros2 == 0 else sum2 + 1

        # If one array has no zeros and the other has zeros, we can only adjust the one with zeros
        # If both have zeros, we can adjust both to meet the minimum sum

        # Check if it's possible to make both sums equal
        if zeros1 == 0 and zeros2 == 0:
            return sum1 if sum1 == sum2 else -1

        # If one array has zeros and the other doesn't
        if zeros1 == 0 and zeros2 > 0:
            if min_sum1 <= min_sum2:
                return min_sum2
            else:
                return -1

        if zeros2 == 0 and zeros1 > 0:
            if min_sum2 <= min_sum1:
                return min_sum1
            else:
                return -1

        # Both have zeros - we can make both sums as large as needed
        # The minimum sum we can achieve is the maximum of the minimum possible sums
        return max(min_sum1, min_sum2)

