class Solution:
    def minimumSum(self, nums: List[int]) -> int:
        n = len(nums)
        min_sum = float('inf')

        # For each middle element j, find the smallest element to the left and right
        for j in range(1, n - 1):
            left_min = float('inf')
            right_min = float('inf')

            # Find minimum value to the left of j
            for i in range(j):
                left_min = min(left_min, nums[i])

            # Find minimum value to the right of j
            for k in range(j + 1, n):
                right_min = min(right_min, nums[k])

            # Check if we have a valid mountain triplet
            if left_min < nums[j] and right_min < nums[j]:
                min_sum = min(min_sum, left_min + nums[j] + right_min)

        return min_sum if min_sum != float('inf') else -1

class Solution:
    def findKOr(self, nums: List[int], k: int) -> int:
        result = 0
        # Check each bit position up to 31
        for i in range(31):
            # Count how many numbers have the i-th bit set
            bit_count = 0
            for num in nums:
                if (num >> i) & 1:
                    bit_count += 1

            # If at least k numbers have the i-th bit set, set this bit in result
            if bit_count >= k:
                result |= (1 << i)

        return result

class Solution:
    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # dp[i] represents the maximum sum of a balanced subsequence ending at index i
        dp = [0] * n
        max_sum = nums[0]

        for i in range(n):
            dp[i] = nums[i]
            max_sum = max(max_sum, dp[i])

            # For each j < i, check if we can extend the subsequence ending at j to include i
            for j in range(i):
                # Check if nums[i] - nums[j] >= i - j
                if nums[i] - nums[j] >= i - j:
                    dp[i] = max(dp[i], dp[j] + nums[i])
            max_sum = max(max_sum, dp[i])

        return max_sum

