class Solution:
    def findChampion(self, grid: List[List[int]]) -> int:
        n = len(grid)
        # Count how many teams each team beats
        beaten_count = [0] * n

        for i in range(n):
            for j in range(n):
                if i != j and grid[i][j] == 1:
                    beaten_count[j] += 1

        # The champion is the team that no one beats (beaten_count is 0)
        for i in range(n):
            if beaten_count[i] == 0:
                return i

class Solution:
    def minOperations(self, nums1: List[int], nums2: List[int]) -> int:
        n = len(nums1)

        def can_satisfy(last1, last2):
            # For each index i from 0 to n-2, we can either keep (nums1[i], nums2[i]) or swap to (nums2[i], nums1[i])
            # We want to minimize swaps while ensuring no element in nums1 exceeds last1 and no element in nums2 exceeds last2

            swaps = 0

            for i in range(n - 1):
                a1, a2 = nums1[i], nums2[i]

                # If we don't swap, we need a1 <= last1 and a2 <= last2
                # If we swap, we need a2 <= last1 and a1 <= last2
                # We want to avoid violations, so we check both options

                # If current values violate the constraints, we must swap
                if a1 > last1 and a2 > last2:
                    # Both values exceed their respective last elements - impossible
                    return float('inf')
                elif a1 > last1:
                    # Only nums1[i] exceeds last1, so we must swap
                    if a2 <= last1 and a1 <= last2:
                        swaps += 1
                    else:
                        return float('inf')
                elif a2 > last2:
                    # Only nums2[i] exceeds last2, so we must swap
                    if a1 <= last1 and a2 <= last2:
                        swaps += 1
                    else:
                        return float('inf')
                # If both are within limits, we don't need to swap (or we can choose not to swap)
                # We don't need to do anything here

            return swaps

        # Try both cases: last elements remain as is or are swapped
        result = float('inf')

        # Case 1: last elements remain as is
        last1, last2 = nums1[-1], nums2[-1]
        result = min(result, can_satisfy(last1, last2))

        # Case 2: swap last elements
        last1, last2 = nums2[-1], nums1[-1]
        result = min(result, can_satisfy(last1, last2))

        # If no valid case, return -1
        return -1 if result == float('inf') else result

