class Solution:
    def minimumSteps(self, s: str) -> int:
        steps = 0
        black_count = 0

        for i in range(len(s)):
            if s[i] == '1':
                black_count += 1
            else:
                # For each white ball, we need to move all black balls that are to its left
                # to the right of it
                steps += black_count

        return steps

class Solution:
    def maxFrequencyScore(self, nums: List[int], k: int) -> int:
        nums.sort()
        n = len(nums)
        max_score = 1

        # Binary search on the answer (maximum frequency)
        left, right = 1, n

        def can_achieve(freq):
            if freq == 1:
                return True

            # Try each possible window of size 'freq' and check if we can make all elements in it equal
            # The optimal target value is the median of the window to minimize cost
            for i in range(n - freq + 1):
                # Consider window [i, i+freq-1]
                # Optimal target is median of this window
                median_idx = i + freq // 2
                target = nums[median_idx]

                # Calculate cost to change all elements in window to target
                total_cost = 0
                for j in range(i, i + freq):
                    total_cost += abs(nums[j] - target)

                if total_cost <= k:
                    return True
            return False

        # Binary search for maximum frequency
        while left < right:
            mid = (left + right + 1) // 2
            if can_achieve(mid):
                left = mid
            else:
                right = mid - 1

        return left

