class Solution:
    def distributeCandies(self, n: int, limit: int) -> int:
        count = 0
        for a in range(limit + 1):
            for b in range(limit + 1):
                c = n - a - b
                if c >= 0 and c <= limit:
                    count += 1
        return count

class Solution:
    def findIntersectionValues(self, nums1: List[int], nums2: List[int]) -> List[int]:
        set2 = set(nums2)
        set1 = set(nums1)

        count1 = 0
        for num in nums1:
            if num in set2:
                count1 += 1

        count2 = 0
        for num in nums2:
            if num in set1:
                count2 += 1

        return [count1, count2]

class Solution:
    def findMinimumOperations(self, s1: str, s2: str, s3: str) -> int:
        # Check if the first characters are the same
        if s1[0] != s2[0] or s2[0] != s3[0]:
            return -1

        # If all strings are already equal
        if s1 == s2 == s3:
            return 0

        # Find the common prefix length
        min_len = min(len(s1), len(s2), len(s3))
        common_prefix = 0

        for i in range(min_len):
            if s1[i] == s2[i] == s3[i]:
                common_prefix += 1
            else:
                break

        # If no common prefix, return -1
        if common_prefix == 0:
            return -1

        # Calculate operations needed
        # We can only remove from the end, so we need to remove all characters
        # beyond the common prefix
        ops = (len(s1) - common_prefix) + (len(s2) - common_prefix) + (len(s3) - common_prefix)

        return ops

class Solution:
    def beautifulSubstrings(self, s: str, k: int) -> int:
        vowels = set('aeiou')
        count = 0
        n = len(s)

        for i in range(n):
            vowels_count = 0
            consonants_count = 0
            for j in range(i, n):
                if s[j] in vowels:
                    vowels_count += 1
                else:
                    consonants_count += 1

                # Check if current substring is beautiful
                if vowels_count == consonants_count and (vowels_count * consonants_count) % k == 0:
                    count += 1

        return count

class Solution:
    def numberOfGoodPartitions(self, nums: List[int]) -> int:
        mod = 10**9 + 7
        n = len(nums)
        if n == 0:
            return 0

        # Find the first and last occurrence of each number
        first_occurrence = {}
        last_occurrence = {}

        for i, num in enumerate(nums):
            if num not in first_occurrence:
                first_occurrence[num] = i
            last_occurrence[num] = i

        # Create intervals [first, last] for each number
        intervals = []
        for num in set(nums):
            first = first_occurrence[num]
            last = last_occurrence[num]
            intervals.append((first, last))

        # Sort intervals by start position
        intervals.sort()

        # Merge overlapping intervals
        merged = []
        for start, end in intervals:
            if not merged:
                merged.append([start, end])
            else:
                last_end = merged[-1][1]
                if start <= last_end:
                    # Overlapping, merge
                    merged[-1][1] = max(last_end, end)
                else:
                    # No overlap, add new interval
                    merged.append([start, end])

        # The number of good partitions is 2^(number of merged intervals - 1)
        # Each interval can be split at the boundaries between intervals
        num_intervals = len(merged)
        result = pow(2, num_intervals - 1, mod)

        return result

class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        max_val = max(nums)
        count = 0
        freq = 0
        left = 0

        for right in range(len(nums)):
            if nums[right] == max_val:
                freq += 1

            # Shrink window if max_val appears more than k times
            while freq >= k:
                if nums[left] == max_val:
                    freq -= 1
                left += 1

            # All subarrays ending at right and starting from left to right (inclusive)
            # will have at least k occurrences of max_val
            if freq >= k:
                count += right - left + 1

        return count

