class Solution:
    def lexicographicallySmallestArray(self, nums: List[int], limit: int) -> List[int]:
        n = len(nums)
        # Create list of (value, index) pairs and sort by value
        arr = [(nums[i], i) for i in range(n)]
        arr.sort()

        # Group indices by value ranges that can be swapped
        result = [0] * n
        used = [False] * n

        for val, idx in arr:
            if used[idx]:
                continue

            # Find all values in the current range that can be swapped with val
            group = []
            for val2, idx2 in arr:
                if not used[idx2] and abs(val - val2) <= limit:
                    group.append((val2, idx2))

            # Sort the group by value to get lexicographically smallest arrangement
            group.sort()

            # Assign the smallest available values to the earliest indices
            for val2, idx2 in group:
                if not used[idx2]:
                    result[idx2] = val2
                    used[idx2] = True

        # Reconstruct the result array with original indices
        final_result = [0] * n
        for val, idx in arr:
            if not used[idx]:
                final_result[idx] = val
            else:
                final_result[idx] = result[idx]

        return final_result

