class Solution:
    def numberGame(self, nums: List[int]) -> List[int]:
        nums.sort()
        arr = []
        for i in range(0, len(nums), 2):
            # Alice removes the smaller one (at i), Bob removes the larger one (at i+1)
            # Bob appends first, then Alice appends
            arr.append(nums[i+1])
            arr.append(nums[i])
        return arr

class Solution:
    def findMissingAndRepeatedValues(self, grid: List[List[int]]) -> List[int]:
        n = len(grid)
        total = n * n
        num_set = set()
        repeated = -1
        missing = -1

        for row in grid:
            for val in row:
                if val in num_set:
                    repeated = val
                else:
                    num_set.add(val)

        # Find missing number by checking which number from 1 to n*n is not in the set
        for i in range(1, total + 1):
            if i not in num_set:
                missing = i
                break

        return [repeated, missing]

class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        operations = 0
        word_list = list(word)
        n = len(word_list)

        for i in range(1, n):
            prev_char = word_list[i-1]
            curr_char = word_list[i]

            # Check if current character and previous character are almost-equal
            if prev_char == curr_char or abs(ord(prev_char) - ord(curr_char)) == 1:
                # We need to change one of them
                operations += 1
                # Change the current character to avoid almost-equality
                # We pick a letter that is not equal to prev_char and not adjacent
                target = 'a'
                while True:
                    if target != prev_char and abs(ord(target) - ord(prev_char)) > 1:
                        word_list[i] = target
                        break
                    target = chr(ord(target) + 1)
                    if target > 'z':
                        break

        return operations

