class Solution:
    def maxPartitionsAfterOperations(self, s: str, k: int) -> int:
        n = len(s)

        # Function to count partitions when given a string
        def count_partitions(s):
            parts = 0
            i = 0
            while i < len(s):
                distinct = set()
                j = i
                while j < len(s):
                    if len(distinct) >= k:
                        break
                    distinct.add(s[j])
                    j += 1
                parts += 1
                i = j
            return parts

        # If k is 1, we can only have single character prefixes
        # The maximum partitions is the number of runs (consecutive same characters)
        if k == 1:
            runs = 1
            for i in range(1, n):
                if s[i] != s[i-1]:
                    runs += 1
            return runs

        # For k >= 2, we try changing each character to each possible letter
        max_partitions = count_partitions(s)

        # Try changing each character at position i to each letter in 'a' to 'z'
        for i in range(n):
            for c in 'abcdefghijklmnopqrstuvwxyz':
                if s[i] == c:
                    continue
                # Create new string with s[i] changed to c
                new_s = s[:i] + c + s[i+1:]
                partitions = count_partitions(new_s)
                max_partitions = max(max_partitions, partitions)

        return max_partitions

