class Solution:
    def getGoodIndices(self, variables: List[List[int]], target: int) -> List[int]:
        result = []
        for i, (a, b, c, m) in enumerate(variables):
            # Calculate (a^b % 10) first
            mod_10 = pow(a, b, 10)
            # Then calculate (mod_10 ^ c) % m
            result_mod = pow(mod_10, c, m)
            if result_mod == target:
                result.append(i)
        return result

class Solution:
    def minimumCost(self, source: str, target: str, original: List[str], changed: List[str], cost: List[int]) -> int:
        import heapq
        from collections import defaultdict

        # Build graph: from char to char with edge weights
        graph = defaultdict(dict)
        for i in range(len(original)):
            x, y = original[i], changed[i]
            c = cost[i]
            if y not in graph[x]:
                graph[x][y] = float('inf')
            graph[x][y] = min(graph[x][y], c)

        # Floyd-Warshall to find shortest path between all pairs of characters
        # Initialize distance matrix
        n = 26
        dist = [[float('inf')] * n for _ in range(n)]

        # Set initial distances
        for i in range(n):
            dist[i][i] = 0

        # Fill in direct edges
        for i in range(len(original)):
            x, y = original[i], changed[i]
            c = cost[i]
            cx = ord(x) - ord('a')
            cy = ord(y) - ord('a')
            dist[cx][cy] = min(dist[cx][cy], c)

        # Floyd-Warshall
        for k in range(n):
            for i in range(n):
                for j in range(n):
                    if dist[i][k] + dist[k][j] < dist[i][j]:
                        dist[i][j] = dist[i][k] + dist[k][j]

        # Calculate total cost
        total_cost = 0
        for i in range(len(source)):
            if source[i] != target[i]:
                s_idx = ord(source[i]) - ord('a')
                t_idx = ord(target[i]) - ord('a')
                if dist[s_idx][t_idx] == float('inf'):
                    return -1
                total_cost += dist[s_idx][t_idx]

        return total_cost

class Solution:
    def missingInteger(self, nums: List[int]) -> int:
        # Find the longest sequential prefix
        prefix_sum = nums[0]
        i = 1

        while i < len(nums):
            if nums[i] == nums[i-1] + 1:
                prefix_sum += nums[i]
                i += 1
            else:
                break

        # Find the smallest integer >= prefix_sum that is not in nums
        x = prefix_sum
        while x in nums:
            x += 1

        return x

class Solution:
    def minimumOperationsToMakeEqual(self, x: int, y: int) -> int:
        if x == y:
            return 0

        # If x is already less than y, we can only increment
        if x < y:
            return y - x

        # If x is greater than y, we can use divisions and decrements
        # Use BFS to find minimum operations
        from collections import deque

        queue = deque([(x, 0)])
        visited = {x}

        while queue:
            curr, ops = queue.popleft()

            # If we reached y
            if curr == y:
                return ops

            # Try all possible operations
            next_vals = []

            # Divide by 11 if divisible
            if curr % 11 == 0:
                next_vals.append(curr // 11)

            # Divide by 5 if divisible
            if curr % 5 == 0:
                next_vals.append(curr // 5)

            # Decrement by 1
            next_vals.append(curr - 1)

            # Increment by 1
            next_vals.append(curr + 1)

            for next_val in next_vals:
                if next_val == y:
                    return ops + 1
                if next_val not in visited and next_val > 0:
                    visited.add(next_val)
                    queue.append((next_val, ops + 1))

        return -1

class Solution:
    def maxFrequencyElements(self, nums: List[int]) -> int:
        from collections import Counter

        # Count frequency of each element
        freq_count = Counter(nums)

        # Find the maximum frequency
        max_freq = max(freq_count.values())

        # Sum up the total count of elements that have the maximum frequency
        total = 0
        for count in freq_count.values():
            if count == max_freq:
                total += max_freq

        return total

class Solution:
    def beautifulIndices(self, s: str, a: str, b: str, k: int) -> List[int]:
        def find_indices(text, pattern):
            indices = []
            start = 0
            while True:
                idx = text.find(pattern, start)
                if idx == -1:
                    break
                indices.append(idx)
                start = idx + 1
            return indices

        a_indices = find_indices(s, a)
        b_indices = find_indices(s, b)

        result = []
        for i in a_indices:
            for j in b_indices:
                if abs(j - i) <= k:
                    result.append(i)
                    break

        return sorted(result)

class Solution:
    def areaOfMaxDiagonal(self, dimensions: List[List[int]]) -> int:
        max_diagonal_squared = 0
        max_area = 0

        for length, width in dimensions:
            diagonal_squared = length * length + width * width
            area = length * width

            if diagonal_squared > max_diagonal_squared:
                max_diagonal_squared = diagonal_squared
                max_area = area
            elif diagonal_squared == max_diagonal_squared and area > max_area:
                max_area = area

        return max_area

class Solution:
    def incremovableSubarrayCount(self, nums: List[int]) -> int:
        n = len(nums)
        count = 0

        # Check all possible subarrays to remove
        for i in range(n):
            for j in range(i, n):
                # Create array after removing subarray [i:j+1]
                remaining = []
                for k in range(n):
                    if k < i or k >= j + 1:
                        remaining.append(nums[k])

                # Check if remaining array is strictly increasing
                is_strictly_increasing = True
                for k in range(1, len(remaining)):
                    if remaining[k] <= remaining[k-1]:
                        is_strictly_increasing = False
                        break

                if is_strictly_increasing:
                    count += 1

        return count

