class Solution:
    def maximumLength(self, s: str) -> int:
        from collections import defaultdict

        # Count frequency of each special substring (made of single character) by length
        length_count = defaultdict(int)

        i = 0
        n = len(s)

        while i < n:
            j = i
            while j < n and s[j] == s[i]:
                j += 1

            # Length of current group of same characters
            group_length = j - i

            # For this group, substrings of length k (1 to group_length) occur (group_length - k + 1) times
            for k in range(1, group_length + 1):
                length_count[k] += (group_length - k + 1)

            i = j

        # Find the maximum length k such that at least one special substring of length k occurs at least 3 times
        max_length = -1
        for k in length_count:
            if length_count[k] >= 3:
                max_length = max(max_length, k)

        return max_length

