class Solution:
    def canSortArray(self, nums: List[int]) -> bool:
        n = len(nums)
        if n <= 1:
            return True

        # Function to count set bits
        def count_set_bits(x):
            count = 0
            while x:
                count += x & 1
                x >>= 1
            return count

        # Group elements by their set bit count
        groups = []
        current_group = []
        current_bit_count = count_set_bits(nums[0])

        for i, num in enumerate(nums):
            if count_set_bits(num) == current_bit_count:
                current_group.append((num, i))
            else:
                # Process the current group
                if current_group:
                    # Sort the group by value to get the smallest elements first
                    sorted_group = sorted(current_group, key=lambda x: x[0])
                    # Update the array with sorted values at their original positions
                    for val, idx in sorted_group:
                        nums[idx] = val
                # Start new group
                current_group = [(num, i)]
                current_bit_count = count_set_bits(num)

        # Process the last group
        if current_group:
            sorted_group = sorted(current_group, key=lambda x: x[0])
            for val, idx in sorted_group:
                nums[idx] = val

        # Check if the array is sorted
        return all(nums[i] <= nums[i+1] for i in range(len(nums) - 1))

class Solution:
    def maxSelectedElements(self, nums: List[int]) -> int:
        nums.sort()
        n = len(nums)
        # dp[i] represents the maximum consecutive elements we can select ending at nums[i]
        dp = [1] * n

        for i in range(1, n):
            # Try to extend a consecutive sequence ending at a previous element
            for j in range(i):
                # If we can increase nums[j] to nums[i] or make nums[i] equal to nums[j] + 1
                # Then we can form a consecutive sequence
                if nums[i] >= nums[j] + 1:
                    dp[i] = max(dp[i], dp[j] + 1)
                elif nums[i] == nums[j]:
                    # If values are equal, we can potentially extend the sequence
                    dp[i] = max(dp[i], dp[j] + 1)

        return max(dp) if dp else 0

