class Solution:
    def maxOperations(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 2:
            return 1

        # The first operation's score is the sum of first two elements
        target_score = nums[0] + nums[1]

        # Count how many operations we can perform with the same score
        operations = 0
        i = 2

        while i + 1 < n:
            if nums[i] + nums[i + 1] == target_score:
                operations += 1
                i += 2
            else:
                break

        return operations + 1

