    def isPossibleToSplit(self, nums: List[int]) -> bool:
        from collections import Counter

        # Count frequency of each element
        freq = Counter(nums)

        # For each unique element, we can use at most 2 copies (one in each group)
        # If any element appears more than 2 times, it's impossible to split
        for count in freq.values():
            if count > 2:
                return False

        return True

class Solution:
    def longestCommonPrefix(self, arr1: List[int], arr2: List[int]) -> int:
        def get_prefixes(arr):
            prefixes = {}
            num = 0
            for val in arr:
                num = num * 10 + val
                temp = num
                while temp > 0:
                    prefixes[temp] = prefixes.get(temp, 0) + 1
                    temp //= 10
            return prefixes

        # Instead of generating all prefixes, we use a more efficient approach
        # We'll track the frequency of prefixes at each length
        prefix_count = {}

        # Process arr1 to build prefix counts
        for num in arr1:
            temp = num
            while temp > 0:
                prefix_count[temp] = prefix_count.get(temp, 0) + 1
                temp //= 10

        max_len = 0
        # For each number in arr2, check if any prefix exists in arr1
        for num in arr2:
            temp = num
            while temp > 0:
                if temp in prefix_count and prefix_count[temp] > 0:
                    max_len = max(max_len, len(str(temp)))
                temp //= 10

        return max_len

