class Solution:
    def minimumBoxes(self, apple: List[int], capacity: List[int]) -> int:
        total_apples = sum(apple)
        capacity.sort(reverse=True)

        boxes_used = 0
        remaining_apples = total_apples

        for cap in capacity:
            if remaining_apples <= 0:
                break
            boxes_used += 1
            remaining_apples -= cap

        return boxes_used

class Solution:
    def maximumHappinessSum(self, happiness: List[int], k: int) -> int:
        happiness.sort(reverse=True)
        total_happiness = 0

        for i in range(k):
            selected_happiness = happiness[i] - i
            if selected_happiness > 0:
                total_happiness += selected_happiness
            else:
                # If happiness becomes non-positive, we can't get any happiness from this selection
                break

        return total_happiness

class Solution:
    def shortestSubstrings(self, arr: List[str]) -> List[str]:
        n = len(arr)
        result = []

        for i in range(n):
            string = arr[i]
            substrings = []

            # Generate all substrings of arr[i]
            for length in range(1, len(string) + 1):
                for start in range(len(string) - length + 1):
                    substr = string[start:start + length]
                    substrings.append(substr)

            # Sort substrings by length, then lexicographically
            substrings.sort(key=lambda x: (len(x), x))

            # Check if any substring does not appear in any other string
            found = False
            for sub in substrings:
                # Check if sub appears in any other string
                appears_in_others = False
                for j in range(n):
                    if i != j and sub in arr[j]:
                        appears_in_others = True
                        break

                if not appears_in_others:
                    result.append(sub)
                    found = True
                    break

            if not found:
                result.append("")

        return result

