class Solution:
    def countSubstrings(self, s: str, c: str) -> int:
        count = 0
        n = len(s)

        for i in range(n):
            if s[i] == c:
                # For each occurrence of c, we can form substrings starting and ending with c
                # The substring can start at i and end at any position from i to n-1 where s[j] == c
                # So we count how many times c appears from i to the end
                for j in range(i, n):
                    if s[j] == c:
                        count += 1

        return count

class Solution:
    def maximumLengthSubstring(self, s: str) -> int:
        n = len(s)
        max_length = 0

        # Try all possible substrings using sliding window
        for i in range(n):
            char_count = {}
            for j in range(i, n):
                char = s[j]
                char_count[char] = char_count.get(char, 0) + 1

                # If any character appears more than twice, break
                if char_count[char] > 2:
                    break

                max_length = max(max_length, j - i + 1)

        return max_length

