class Solution:
    def sumOfTheDigitsOfHarshadNumber(self, x: int) -> int:
        digit_sum = 0
        temp = x

        while temp > 0:
            digit_sum += temp % 10
            temp //= 10

        if x % digit_sum == 0:
            return digit_sum
        else:
            return -1

class Solution:
    def minimumDistance(self, points: List[List[int]]) -> int:
        n = len(points)
        if n == 3:
            # With only 3 points, removing one leaves 2 points with distance 0
            return 0

        # Function to compute Manhattan distance between two points
        def manhattan(p1, p2):
            return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

        # Precompute all pairwise Manhattan distances
        max_dist_after_removal = float('inf')

        # Try removing each point and find the maximum distance among remaining points
        for i in range(n):
            max_remaining = 0
            for j in range(n):
                if i != j:
                    max_remaining = max(max_remaining, manhattan(points[i], points[j]))
            max_dist_after_removal = min(max_dist_after_removal, max_remaining)

        return max_dist_after_removal

class Solution:
    def longestMonotonicSubarray(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        max_increasing = 1
        max_decreasing = 1
        current_increasing = 1
        current_decreasing = 1

        for i in range(1, n):
            if nums[i] > nums[i-1]:
                current_increasing += 1
                max_increasing = max(max_increasing, current_increasing)
                current_decreasing = 1
            elif nums[i] < nums[i-1]:
                current_decreasing += 1
                max_decreasing = max(max_decreasing, current_decreasing)
                current_increasing = 1
            # If nums[i] == nums[i-1], both sequences reset to 1

        return max(max_increasing, max_decreasing)

