                # We need to find the largest i (closest to 0) such that the distance between char_idx and i is <= k

                # The distance between two characters is min(|a-b|, 26 - |a-b|)
                # We want to go backwards as much as possible, so we try from char_idx-1 down to 0

                # We go backwards from char_idx to 0
                for i in range(char_idx - 1, -1, -1):
                    dist = min(abs(char_idx - i), 26 - abs(char_idx - i))
                    if dist <= k:
                        result.append(chr(ord('a') + i))
                        k -= dist
                        break
                else:
                    # If we didn't find any valid character, we go to the closest one
                    # This should not happen given constraints
                    result.append(chr(ord('a') + char_idx))
        return "".join(result)

class Solution:
    def minOperationsToMakeMedianK(self, nums: List[int], k: int) -> int:
        n = len(nums)
        nums.sort()
        median_idx = n // 2

        # If median is already k, return 0
        if n % 2 == 1:
            # Odd length: median is at index n//2
            if nums[median_idx] == k:
                return 0
            return abs(nums[median_idx] - k)

        # Even length: median is the larger of nums[n//2-1] and nums[n//2]
        # We need to make the larger of these two equal to k
        left_median = nums[median_idx - 1]
        right_median = nums[median_idx]

        # The median is defined as the larger of the two middle elements
        # So we need to change the larger one to k
        if left_median >= right_median:
            # left_median is the larger one
            return abs(left_median - k)
        else:
            # right_median is the larger one
            return abs(right_median - k)

