class Solution:
    def maximumPrimeDifference(self, nums: List[int]) -> int:
        def is_prime(n):
            if n < 2:
                return False
            if n == 2:
                return True
            if n % 2 == 0:
                return False
            for i in range(3, int(n**0.5) + 1, 2):
                if n % i == 0:
                    return False
            return True

        n = len(nums)
        first_prime_idx = -1
        last_prime_idx = -1

        for i in range(n):
            if is_prime(nums[i]):
                if first_prime_idx == -1:
                    first_prime_idx = i
                last_prime_idx = i

        return last_prime_idx - first_prime_idx

class Solution:
    def findKthSmallest(self, coins: List[int], k: int) -> int:
        def count_achievable(amount):
            count = 0
            for coin in coins:
                if amount % coin == 0:
                    count += 1
            return count

        # Binary search on the answer
        left, right = 1, k * min(coins)

        while left < right:
            mid = (left + right) // 2
            # Count how many amounts <= mid can be formed
            achievable = 0
            for coin in coins:
                if mid % coin == 0:
                    achievable += 1

            # If we can form at least k amounts <= mid, then answer is <= mid
            if achievable >= k:
                right = mid
            else:
                left = mid + 1

        return left

class Solution:
    def findKthSmallest(self, coins: List[int], k: int) -> int:
        import math
        from typing import List

        def count_achievable(amount):
            # Use inclusion-exclusion to count distinct amounts <= amount that can be formed
            n = len(coins)
            total = 0

            # Iterate over all non-empty subsets of coins
            for mask in range(1, 1 << n):
                # Compute LCM of coins in the subset
                lcm_val = 1
                subset_size = 0

                for i in range(n):
                    if mask & (1 << i):
                        subset_size += 1
                        if lcm_val == 1:
                            lcm_val = coins[i]
                        else:
                            g = math.gcd(lcm_val, coins[i])
                            lcm_val = lcm_val * coins[i] // g
                            # Early termination if LCM exceeds amount
                            if lcm_val > amount:
                                break

                if subset_size == 0:
                    continue

                # Count multiples of LCM that are <= amount
                multiples = amount // lcm_val

                # Inclusion-exclusion: odd-sized subsets add, even-sized subtract
                if subset_size % 2 == 1:
                    total += multiples
                else:
                    total -= multiples

            return total

        # Binary search on the answer
        left, right = 1, k * min(coins)

        while left < right:
            mid = (left + right) // 2
            if count_achievable(mid) < k:
                left = mid + 1
            else:
                right = mid

        return left

class Solution:
    def minimumValueSum(self, nums: List[int], andValues: List[int]) -> int:
        n, m = len(nums), len(andValues)

        # DP with state: dp[i][j] = minimum sum to partition nums[0:i] into j subarrays
        # We'll use a different approach: iterate through positions and use DP with memoization

        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(pos, idx):
            # pos: current position in nums (we've processed up to pos)
            # idx: current index in andValues (we need to form idx+1 subarrays)

            if idx == m:
                return 0 if pos == n else float('inf')

            if pos == n:
                return float('inf')

            # Option 1: skip current position (not valid as we need to form subarrays)
            # We need to form a subarray ending at some position >= pos

            result = float('inf')
            # Try all possible end positions for current subarray
            for end in range(pos, n):
                # Check if nums[pos:end+1] has bitwise AND equal to andValues[idx]
                current_and = nums[pos]
                for j in range(pos + 1, end + 1):
                    current_and &= nums[j]

                # If the AND value matches andValues[idx]
                if current_and == andValues[idx]:
                    next_result = dp(end + 1, idx + 1)
                    if next_result != float('inf'):
                        result = min(result, nums[end] + next_result)

            return result if result != float('inf') else -1

        result = dp(0, 0)
        return result if result != float('inf') else -1

