class Solution:
    def sumOfEncryptedInt(self, nums: List[int]) -> int:
        def encrypt(x):
            digits = [int(d) for d in str(x)]
            max_digit = max(digits)
            return int(str(max_digit) * len(str(x)))

        return sum(encrypt(num) for num in nums)

class Solution:
    def unmarkedSumArray(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        n = len(nums)
        marked = [False] * n
        total_sum = sum(nums)
        answer = []

        # Create list of (value, index) pairs and sort by value then index
        indexed_nums = [(nums[i], i) for i in range(n)]
        indexed_nums.sort()

        for index, k in queries:
            # Mark the element at given index if not already marked
            if not marked[index]:
                marked[index] = True
                total_sum -= nums[index]

            # Mark k smallest unmarked elements (by value, then by index)
            count = 0
            for val, idx in indexed_nums:
                if not marked[idx]:
                    if count < k:
                        marked[idx] = True
                        total_sum -= val
                        count += 1
                    else:
                        break

            answer.append(total_sum)

        return answer

class Solution:
    def sumOfPower(self, nums: List[int], k: int) -> int:
        MOD = 10**9 + 7
        n = len(nums)

        # dp[s] = total contribution from all subsets that sum to s
        # The contribution is 2^(n - size) where size is the number of elements in the subset
        # We use dp to track the sum of contributions for each sum

        # Start with empty subset
        dp = {0: 1}  # sum: total contribution (2^(n - size))

        for num in nums:
            new_dp = {}
            for prev_sum, contribution in dp.items():
                # Option 1: don't include current element
                if prev_sum not in new_dp:
                    new_dp[prev_sum] = 0
                new_dp[prev_sum] = (new_dp[prev_sum] + contribution) % MOD

                # Option 2: include current element in the subset
                new_sum = prev_sum + num
                if new_sum <= k:
                    # When we include the current element, we double the contribution
                    # because we're adding one more element to the subset, and each element
                    # contributes a factor of 2 to the total count of subsequences
                    new_contribution = (contribution * 2) % MOD
                    if new_sum not in new_dp:
                        new_dp[new_sum] = 0
                    new_dp[new_sum] = (new_dp[new_sum] + new_contribution) % MOD

            dp = new_dp

        # Answer is the contribution from subsets that sum to k
        return dp.get(k, 0)

