class Solution:
    def minimumSubarrayLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        min_len = float('inf')

        # Check all possible subarrays
        for i in range(n):
            or_val = 0
            for j in range(i, n):
                or_val |= nums[j]
                # If current OR value meets or exceeds k, update minimum length
                if or_val >= k:
                    min_len = min(min_len, j - i + 1)

        return min_len if min_len != float('inf') else -1

class Solution:
    def minimumLevels(self, possible: List[int]) -> int:
        n = len(possible)
        total_points = 0

        # Calculate total points if all levels are clear (for Bob)
        for p in possible:
            if p == 1:
                total_points += 1
            else:
                total_points -= 1

        # If total points is negative or zero, Alice can never gain more points
        # because Bob will always have at least as many points as Alice
        if total_points <= 0:
            return -1

