class Solution:
    def scoreOfString(self, s: str) -> int:
        score = 0
        for i in range(len(s) - 1):
            score += abs(ord(s[i]) - ord(s[i + 1]))
        return score

class Solution:
    def numberOfSpecialChars(self, word: str) -> int:
        lowercase = set()
        uppercase = set()

        # Separate lowercase and uppercase letters
        for char in word:
            if char.islower():
                lowercase.add(char)
            elif char.isupper():
                uppercase.add(char)

        # Count letters that appear in both lowercase and uppercase
        count = 0
        for char in lowercase:
            if char.upper() in uppercase:
                count += 1

        return count

class Solution:
    def isValid(self, word: str) -> bool:
        # Check minimum length
        if len(word) < 3:
            return False

        # Check if contains only digits and English letters
        for char in word:
            if not (char.isdigit() or char.isalpha()):
                return False

        # Check for at least one vowel
        vowels = set('aeiouAEIOU')
        has_vowel = any(char in vowels for char in word)
        if not has_vowel:
            return False

        # Check for at least one consonant (non-vowel letter)
        has_consonant = any(char.isalpha() and char not in vowels for char in word)
        if not has_consonant:
            return False

        return True

class Solution:
    def minAnagramLength(self, s: str) -> int:
        from collections import Counter

        # Count frequency of each character in s
        char_count = Counter(s)

        # The length of t must divide the length of s
        # Also, for each character, the frequency must be divisible by the length of t
        n = len(s)

        # Try all possible lengths from 1 to n
        for length in range(1, n + 1):
            if n % length != 0:
                continue

            # Check if each character's frequency is divisible by length
            valid = True
            for count in char_count.values():
                if count % length != 0:
                    valid = False
                    break

            if valid:
                return length

        return n

class Solution:
    def minAnagramLength(self, s: str) -> int:
        from collections import Counter

        # Count frequency of each character in s
        char_count = Counter(s)
        n = len(s)

        # The length of t must divide the length of s
        # Also, for each character, the frequency must be divisible by the length of t
        # We need to find the minimum length such that:
        # 1. n % length == 0
        # 2. For each character, char_count[char] % length == 0

        # Find all divisors of n
        divisors = []
        for i in range(1, int(n**0.5) + 1):
            if n % i == 0:
                divisors.append(i)
                if i != n // i:
                    divisors.append(n // i)

        # Check each divisor to find the minimum valid length
        for length in sorted(divisors):
            valid = True
            for count in char_count.values():
                if count % length != 0:
                    valid = False
                    break
            if valid:
                return length

        return n

