class Solution:
    def canMakeSquare(self, grid: List[List[str]]) -> bool:
        # Check all 2x2 submatrices in the 3x3 grid
        for i in range(2):
            for j in range(2):
                # Extract the 2x2 submatrix starting at (i,j)
                cells = [
                    grid[i][j], grid[i][j+1],
                    grid[i+1][j], grid[i+1][j+1]
                ]

                # Count B and W in this 2x2 square
                count_b = cells.count('B')
                count_w = cells.count('W')

                # If we have at most one different color, we can change one cell
                # to make all 4 cells the same color
                if count_b == 0 or count_w == 0 or count_b == 4 or count_w == 4:
                    return True

                # If we have exactly 1 or 2 of one color, we can change at most one cell
                # to make all 4 cells the same color
                if count_b <= 1 or count_w <= 1:
                    return True

                # If we have 3 of one color and 1 of the other, we can change the single one
                if count_b == 3 or count_w == 3:
                    return True

        return False

class Solution:
    def numberOfRightTriangles(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])

        # Count the number of 1s in each row and each column
        row_count = [0] * m
        col_count = [0] * n

        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    row_count[i] += 1
                    col_count[j] += 1

        result = 0

        # For each cell that is 1, check if it can be the right angle
        # If (i,j) is 1, then we need a 1 in row i and a 1 in column j
        # The right angle is at (i,j), and we need one 1 in row i (excluding (i,j)) 
        # and one 1 in column j (excluding (i,j))
        for i in range(m):
            for j in range(n):
                if grid[i][j] == 1:
                    # Number of 1s in row i excluding current position
                    left_in_row = row_count[i] - 1
                    # Number of 1s in column j excluding current position
                    left_in_col = col_count[j] - 1
                    # If both exist, we can form left_in_row * left_in_col right triangles
                    if left_in_row > 0 and left_in_col > 0:
                        result += left_in_row * left_in_col

        return result

class Solution:
    def findPermutationDifference(self, s: str, t: str) -> int:
        diff = 0
        char_map = {}

        # Create mapping of character to its index in s
        for i, char in enumerate(s):
            char_map[char] = i

        # Calculate absolute difference for each character in t
        for i, char in enumerate(t):
            if char in char_map:
                diff += abs(i - char_map[char])

        return diff

class Solution:
    def isArraySpecial(self, nums: List[int]) -> bool:
        if len(nums) <= 1:
            return True

        for i in range(len(nums) - 1):
            # Check if adjacent elements have different parity
            if (nums[i] % 2) == (nums[i + 1] % 2):
                return False

        return True

class Solution:
    def numberOfPairs(self, nums1: List[int], nums2: List[int], k: int) -> int:
        count = 0
        for i in range(len(nums1)):
            for j in range(len(nums2)):
                if nums1[i] % (nums2[j] * k) == 0:
                    count += 1
        return count

class Solution:
    def compressedString(self, word: str) -> str:
        comp = ""
        i = 0
        n = len(word)

        while i < n:
            c = word[i]
            count = 0
            # Count consecutive occurrences of c, up to 9
            while i < n and word[i] == c and count < 9:
                count += 1
                i += 1

            # Append count and character to result
            if count > 0:
                comp += str(count) + c

        return comp

class Solution:
    def minimumSubstringsInPartition(self, s: str) -> int:
        n = len(s)
        # dp[i] represents the minimum number of balanced substrings for s[:i]
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        for i in range(1, n + 1):
            # Try all possible ending positions of the last substring
            for j in range(i):
                # Check if s[j:i] is balanced
                if self.isBalanced(s[j:i]):
                    dp[i] = min(dp[i], dp[j] + 1)

        return dp[n]

    def isBalanced(self, substr: str) -> bool:
        # Count frequency of each character
        freq = {}
        for c in substr:
            freq[c] = freq.get(c, 0) + 1

        # All characters must have the same frequency
        if not freq:
            return True

        count = freq[list(freq.keys())[0]]
        for freq_val in freq.values():
            if freq_val != count:
                return False

        return True

