class Solution:
    def occurrencesOfElement(self, nums: List[int], queries: List[int], x: int) -> List[int]:
        # Find all indices where x occurs
        indices = []
        for i, num in enumerate(nums):
            if num == x:
                indices.append(i)

        # If x doesn't exist in nums, return -1 for all queries
        if not indices:
            return [-1] * len(queries)

        # For each query, check if the requested occurrence exists
        result = []
        for query in queries:
            if query <= len(indices):
                result.append(indices[query - 1])
            else:
                result.append(-1)

        return result

class Solution:
    def minimumChairs(self, s: str) -> int:
        chairs_needed = 0
        current_people = 0

        for event in s:
            if event == 'E':
                current_people += 1
                chairs_needed = max(chairs_needed, current_people)
            else:  # event == 'L'
                current_people -= 1

        return chairs_needed

class Solution:
    def countDays(self, days: int, meetings: List[List[int]]) -> int:
        # Sort meetings by start time
        meetings.sort()

        # Use a list to track meeting intervals
        intervals = []

        for start, end in meetings:
            # Merge overlapping intervals
            if not intervals or intervals[-1][1] < start:
                intervals.append([start, end])
            else:
                # Merge with existing interval
                intervals[-1][1] = max(intervals[-1][1], end)

        # Count available days
        available = 0
        prev_day = 1

        for start, end in intervals:
            # Days between prev_day and start are available
            if prev_day < start:
                available += start - prev_day
            # Update prev_day to end + 1
            prev_day = end + 1

        # Add remaining days after last meeting
        if prev_day <= days:
            available += days - prev_day

        return available

