class Solution:
    def minimumDifference(self, nums: List[int], k: int) -> int:
        n = len(nums)
        min_diff = float('inf')

        # For each starting position, compute OR values of all subarrays starting at that position
        for i in range(n):
            or_val = 0
            for j in range(i, n):
                or_val |= nums[j]
                min_diff = min(min_diff, abs(k - or_val))

        return min_diff

class Solution:
    def maxTotalReward(self, rewardValues: List[int]) -> int:
        rewardValues.sort()
        n = len(rewardValues)
        # dp[x] represents whether we can achieve total reward x
        dp = {0: True}

        for val in rewardValues:
            # Create a new dp state to avoid using updated values in same iteration
            new_dp = dp.copy()
            for total in dp:
                if total + val <= 2000:  # Maximum possible reward is bounded by constraints
                    new_dp[total + val] = True
            dp = new_dp

        # Return the maximum total reward achievable
        return max(dp.keys())

