class Solution:
    def minimumAverage(self, nums: List[int]) -> float:
        nums.sort()
        averages = []
        n = len(nums)

        for i in range(n // 2):
            min_element = nums[i]
            max_element = nums[n - 1 - i]
            averages.append((min_element + max_element) / 2)

        return min(averages)

class Solution:
    def minimumArea(self, grid: List[List[int]]) -> int:
        # Find the bounding rectangle that contains all 1s
        min_row, max_row = float('inf'), float('-inf')
        min_col, max_col = float('inf'), float('-inf')

        for i in range(len(grid)):
            for j in range(len(grid[0])):
                if grid[i][j] == 1:
                    min_row = min(min_row, i)
                    max_row = max(max_row, i)
                    min_col = min(min_col, j)
                    max_col = max(max_col, j)

        # Calculate the area of the bounding rectangle
        height = max_row - min_row + 1
        width = max_col - min_col + 1

        return height * width

class Solution:
    def getEncryptedString(self, s: str, k: int) -> str:
        encrypted = []
        n = len(s)

        for i in range(n):
            # Find the character k positions after s[i] in a cyclic manner
            # The k-th character after s[i] is at position (i + k) % n
            target_index = (i + k) % n
            encrypted.append(s[target_index])

        return ''.join(encrypted)

class Solution:
    def validStrings(self, n: int) -> List[str]:
        result = []

        def backtrack(s):
            if len(s) == n:
                result.append(s)
                return

            # Try '0' and '1' at the end
            for digit in '01':
                # Check if adding this digit creates a valid substring of length 2
                if len(s) >= 2:
                    # Last two characters must contain at least one '1'
                    if s[-1] == '0' and s[-2] == '0':
                        continue  # Invalid: last two are "00"
                backtrack(s + digit)

        # Start with empty string
        backtrack("")
        return result

