class Solution:
    def numberOfSubmatrices(self, grid: List[List[str]]) -> int:
        m, n = len(grid), len(grid[0])
        result = 0

        # Check all possible submatrices starting from (i, j)
        for i in range(m):
            for j in range(n):
                # Only consider submatrices that include (0,0)
                # So the top-left corner must be (0,0)
                # We need to find all submatrices that contain (0,0)
                # and have equal X and Y count with at least one X

                # We'll iterate through all possible bottom-right corners
                # such that the submatrix includes (0,0)
                for di in range(i + 1):
                    for dj in range(j + 1):
                        # Submatrix from (0,0) to (di, dj)
                        x_count = 0
                        y_count = 0
                        for r in range(di + 1):
                            for c in range(dj + 1):
                                if r >= i and c >= j:
                                    continue
                                if grid[r][c] == 'X':
                                    x_count += 1
                                elif grid[r][c] == 'Y':
                                    y_count += 1

                        # Check if we have equal frequency of X and Y and at least one X
                        if x_count == y_count and x_count > 0:
                            result += 1

        return result

