class Solution:
    def minimumCost(self, target: str, words: List[str], costs: List[int]) -> int:
        from collections import defaultdict

        # Group words by their ending character and store (cost, length) pairs
        char_words = defaultdict(list)
        for word, cost in zip(words, costs):
            for i, char in enumerate(word):
                char_words[char].append((cost, len(word)))

        # Check if every character in target has at least one word that ends with it
        for char in target:
            if char not in char_words:
                return -1

        # DP array: dp[i] = minimum cost to form target[:i]
        n = len(target)
        dp = [float('inf')] * (n + 1)
        dp[0] = 0

        # For each position in target
        for i in range(1, n + 1):
            char = target[i - 1]

            # For each word that ends with the current character
            for cost, word_len in char_words[char]:
                # We can append this word to a prefix ending at position i - word_len
                if i >= word_len:
                    dp[i] = min(dp[i], dp[i - word_len] + cost)

        return dp[n] if dp[n] != float('inf') else -1

class Solution:
    def getSmallestString(self, s: str) -> str:
        # Convert string to list for easy manipulation
        chars = list(s)
        n = len(s)

        # Find the first pair of adjacent digits with the same parity
        # that can be swapped to get a lexicographically smaller string
        for i in range(n - 1):
            # Check if current digit and next digit have same parity
            digit1 = int(chars[i])
            digit2 = int(chars[i + 1])

            # Same parity: both odd or both even
            if (digit1 % 2) == (digit2 % 2):
                # Check if swapping would make the string lexicographically smaller
                # We want to swap if the next digit is smaller than current digit
                if digit2 < digit1:
                    # Swap them
                    chars[i], chars[i + 1] = chars[i + 1], chars[i]
                    break

        return ''.join(chars)

class Solution:
    def minimumCost(self, m: int, n: int, horizontalCut: List[int], verticalCut: List[int]) -> int:
        total_cost = 0

        # Add the cost of all horizontal cuts
        for cost in horizontalCut:
            total_cost += cost

        # Add the cost of all vertical cuts
        for cost in verticalCut:
            total_cost += cost

        return total_cost

class Solution:
    def minimumCost(self, m: int, n: int, horizontalCut: List[int], verticalCut: List[int]) -> int:
        # The key insight is that each cut operation is performed once, regardless of the piece size
        # We need exactly (m-1) horizontal cuts and (n-1) vertical cuts
        # Each cut has a fixed cost as given in the arrays
        # Therefore, the total cost is simply the sum of all horizontal cut costs plus the sum of all vertical cut costs

        return sum(horizontalCut) + sum(verticalCut)

