class Solution:
    def maxOperations(self, s: str) -> int:
        n = len(s)
        # Count total number of 1s
        total_ones = s.count('1')

        # If there are 0 or 1 ones, no operations possible
        if total_ones <= 1:
            return 0

        # Find positions of all 1s
        ones = []
        for i in range(n):
            if s[i] == '1':
                ones.append(i)

        # For each pair of consecutive 1s, add the number of zeros between them
        operations = 0
        for i in range(1, len(ones)):
            # Number of zeros between ones[i-1] and ones[i]
            zeros_between = ones[i] - ones[i-1] - 1
            operations += zeros_between

        return operations

