class Solution:
    def finalPositionOfSnake(self, n: int, commands: List[str]) -> int:
        row, col = 0, 0
        for command in commands:
            if command == "RIGHT":
                col += 1
            elif command == "LEFT":
                col -= 1
            elif command == "DOWN":
                row += 1
            elif command == "UP":
                row -= 1
        return row * n + col

class Solution:
    def clearDigits(self, s: str) -> str:
        stack = []
        for char in s:
            if char.isdigit():
                if stack:
                    stack.pop()
            else:
                stack.append(char)
        return ''.join(stack)

class Solution:
    def maximumLength(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if n == 0:
            return 0

        max_length = 0

        # Try every possible starting position
        for start in range(n):
            # Try to extend from start position
            current_length = 1
            changes = 0
            last_val = nums[start]

            for next_idx in range(start + 1, n):
                if nums[next_idx] != last_val:
                    changes += 1
                    if changes > k:
                        break
                last_val = nums[next_idx]
                current_length += 1

            max_length = max(max_length, current_length)

        return max_length

