class Solution:
    def minOperations(self, nums: List[int]) -> int:
        n = len(nums)
        # Convert to list for mutation
        arr = nums[:]
        operations = 0

        # Process from left to right
        for i in range(n - 2):
            # If current element is 0, we need to flip it
            if arr[i] == 0:
                # Flip the next three elements (i, i+1, i+2)
                arr[i] = 1
                arr[i+1] = 1 - arr[i+1]
                arr[i+2] = 1 - arr[i+2]
                operations += 1

        # Check if all elements are 1
        for i in range(n):
            if arr[i] == 0:
                return -1

        return operations

class Solution:
    def maximumPoints(self, enemyEnergies: List[int], currentEnergy: int) -> int:
        enemyEnergies.sort()
        points = 0
        energy = currentEnergy

        for enemy_energy in enemyEnergies:
            if energy >= enemy_energy:
                points += 1
                energy -= enemy_energy
                if points > 0:
                    energy += enemy_energy * points

        return points

