class Solution:
    def countSubarrays(self, nums: List[int], k: int) -> int:
        count = 0
        n = len(nums)

        # For each starting position, extend the subarray and track the running AND
        for i in range(n):
            running_and = nums[i]
            if running_and == k:
                # If current element equals k, we can extend from this point
                # All subarrays starting at i and ending at or after i will have AND value k
                # only if the running AND remains k throughout
                count += 1
                # Continue extending from i to find more valid subarrays
                for j in range(i + 1, n):
                    running_and &= nums[j]
                    if running_and == k:
                        count += 1
                    elif running_and < k:
                        # If running AND becomes less than k, no point continuing
                        # because AND operation can only reduce or stay same
                        break

        return count

