class Solution:
    def losingPlayer(self, x: int, y: int) -> str:
        # Each turn, a player needs to pick coins summing to 115
        # We can form 115 using 75 + 4*10 = 115
        # So each turn requires 1 coin of 75 and 4 coins of 10

        # Total number of complete turns possible
        turns = min(x, y // 4)

        # If total turns is odd, Alice wins (since Alice goes first)
        # If total turns is even, Bob wins

        if turns % 2 == 1:
            return "Alice"
        else:
            return "Bob"

class Solution:
    def minimumLength(self, s: str) -> int:
        left = 0
        right = len(s) - 1

        while left < right:
            if s[left] == s[right]:
                # Try to remove pairs from both ends
                # Skip all consecutive identical characters from both ends
                while left < right and s[left] == s[left + 1]:
                    left += 1
                while left < right and s[right] == s[right - 1]:
                    right -= 1
                # If both ends are equal and we can remove them, skip them
                if s[left] == s[right]:
                    left += 1
                    right -= 1
                else:
                    break
            else:
                break

        return right - left + 1

