class Solution:
    def winningPlayerCount(self, n: int, pick: List[List[int]]) -> int:
        # Count frequency of each color picked by each player
        color_count = {}
        for player, color in pick:
            if color not in color_count:
                color_count[color] = {}
            if player not in color_count[color]:
                color_count[color][player] = 0
            color_count[color][player] += 1

        # Count how many players win
        wins = 0
        for player in range(n):
            # Check if player wins: they need at least (player + 1) balls of the same color
            color_count_for_player = 0
            for color in color_count:
                if player in color_count[color]:
                    if color_count[color][player] > player:
                        wins += 1
                        break

        return wins

class Solution:
    def minFlips(self, grid: List[List[int]]) -> int:
        m, n = len(grid), len(grid[0])
        min_flips = float('inf')

        # Check all rows
        row_flips = 0
        for i in range(m):
            row_flips = 0
            for j in range(n // 2):
                if grid[i][j] != grid[i][n - 1 - j]:
