class Solution:
    def countKConstraintSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        total = 0

        # Check every possible substring
        for i in range(n):
            count_0 = 0
            count_1 = 0
            for j in range(i, n):
                if s[j] == '0':
                    count_0 += 1
                else:
                    count_1 += 1

                # Check if either 0s or 1s is at most k
                if count_0 <= k or count_1 <= k:
                    total += 1

        return total

class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        if n == 1:
            for d in range(9, -1, -1):
                if d % k == 0:
                    return str(d)
            return "0"

        half_len = n // 2
        mid = n % 2

        # Try to build the first half as all 9s
        first_str = "9" * half_len

        # Case 1: even n
        if mid == 0:
            # Try palindrome with first half as all 9s
            palindrome = first_str + first_str[::-1]
            if self.is_divisible_by_k(palindrome, k):
                return palindrome

            # Try all first halves from max down to 1
            # Instead of converting to int, we'll generate the first half string
            # and check divisibility without converting the full number to int
            for first in range(int(first_str), 0, -1):
                # Convert first to string with proper length
                first_str = str(first)
                if len(first_str) < half_len:
                    first_str = "0" * (half_len - len(first_str)) + first_str
                first_str = first_str.zfill(half_len)

                palindrome = first_str + first_str[::-1]
                if self.is_divisible_by_k(palindrome, k):
                    return palindrome

            return "9" * n

        # Case 2: odd n
        else:
            # Try first half as all 9s with middle digit from 9 to 0
            for mid_digit in range(9, -1, -1):
                palindrome = first_str + str(mid_digit) + first_str[::-1]
                if self.is_divisible_by_k(palindrome, k):
                    return palindrome

            # Try all first halves from max down to 1
            for first in range(int(first_str), 0, -1):
                first_str = str(first)
                if len(first_str) < half_len:
