class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        if n == 1:
            for d in range(9, -1, -1):
                if d % k == 0:
                    return str(d)
            return "0"

        half_len = n // 2
        mid = n % 2

        # Try to build the first half as all 9s
        first_str = "9" * half_len

        # Case 1: even n
        if mid == 0:
            # Try palindrome with first half as all 9s
            palindrome = first_str + first_str[::-1]
            if self.is_divisible_by_k(palindrome, k):
                return palindrome

            # Try all first halves from max down to 1
            # We'll generate the first half string directly without converting to int
            # Start from the maximum possible first half (all 9s) and go down
            max_first = int(first_str)

            # We need to generate numbers from max_first down to 1 with exactly half_len digits
            # Instead of converting back to string, we generate the palindrome directly
            for first in range(max_first, 0, -1):
                # Convert first to string with proper length
                first_str = str(first)
                if len(first_str) < half_len:
                    first_str = "0" * (half_len - len(first_str)) + first_str
                else:
                    first_str = first_str.zfill(half_len)
                    first_str = first_str[:half_len]

                palindrome = first_str + first_str[::-1]
                if self.is_divisible_by_k(palindrome, k):
                    return palindrome

            return "9" * n

        # Case 2: odd n
        else:
            # Try first half as all 9s with middle digit from 9 to 0
            for mid_digit in range(9, -1, -1):
                palindrome = first_str + str(mid_digit) + first_str[::-1]
                if self.is_divisible_by_k(palindrome, k):
                    return palindrome

            # Try all first halves from max down to 1
            max_first = int(first_str)
            for first in range(max_first, 0, -1):
