class Solution:
    def maxScore(self, grid: List[List[int]]) -> int:
        n = len(grid)
        m = len(grid[0])

        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(row, used):
            if row == n:
                return 0

            result = dp(row + 1, used)

            max_score = 0
            for col in range(m):
                val = grid[row][col]
                if val not in used:
                    new_used = used | {val}
                    score = val + dp(row + 1, new_used)
                    max_score = max(max_score, score)

            return max_score

        return dp(0, frozenset())

