class Solution:
    def maximumSubarrayXor(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        def get_max_xor_score(l, r):
            max_score = 0
            n = r - l + 1
            # Try all subarrays in the range [l, r]
            for i in range(l, r + 1):
                for j in range(i, r + 1):
                    subarray = nums[i:j+1]
                    # Compute XOR score by repeatedly applying XOR operations
                    a = subarray[:]
                    while len(a) > 1:
                        new_a = []
                        for k in range(len(a) - 1):
                            new_a.append(a[k] ^ a[k + 1])
                        a = new_a
                    score = a[0]
                    max_score = max(max_score, score)
            return max_score

        result = []
        for l, r in queries:
            result.append(get_max_xor_score(l, r))
        return result

class Solution:
