        def get_max_xor_score(l, r):
            max_score = 0
            n = r - l + 1
            # Precompute XOR scores for all subarrays efficiently
            # For a subarray of length k, we can compute the final XOR score using bit manipulation
            # However, we'll use a direct but optimized approach for small arrays

            # Try all subarrays in the range [l, r]
            for i in range(l, r + 1):
                for j in range(i, r + 1):
                    # Compute XOR score for subarray nums[i:j+1]
                    a = nums[i:j+1][:]
                    while len(a) > 1:
                        new_a = []
                        for k in range(len(a) - 1):
                            new_a.append(a[k] ^ a[k + 1])
                        a = new_a
                    max_score = max(max_score, a[0])
            return max_score

        result = []
        for l, r in queries:
            result.append(get_max_xor_score(l, r))
