class Solution:
    def findMaximumScore(self, nums: List[int]) -> int:
        n = len(nums)
        stack = []
        total_score = 0

        for i in range(n):
            # While stack is not empty and current element is greater than or equal to the top of stack
            while stack and nums[i] >= nums[stack[-1]]:
                prev_idx = stack.pop()
                # The jump from prev_idx to i contributes (i - prev_idx) * nums[prev_idx]
                total_score += (i - prev_idx) * nums[prev_idx]

            stack.append(i)

        return total_score

