    def minValidStrings(self, words: List[str], target: str) -> int:
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(i):
            if i == len(target):
                return 0

            min_count = float('inf')

            # Try each word as a prefix
            for word in words:
                # Check if word is a prefix of target starting at position i
                if target[i:].startswith(word):
                    # Recursively solve for the remaining part
                    remaining = dp(i + len(word))
                    if remaining != float('inf'):
                        min_count = min(min_count, 1 + remaining)

            return min_count if min_count != float('inf') else -1

        result = dp(0)
        return result if result != float('inf') else -1

