class Solution:
    def resultsArray(self, nums: List[int], k: int) -> List[int]:
        n = len(nums)
        result = []

        for i in range(n - k + 1):
            subarray = nums[i:i + k]

            # Check if the subarray is sorted in ascending order and has consecutive elements
            is_sorted = all(subarray[j] <= subarray[j + 1] for j in range(k - 1))
            if not is_sorted:
                result.append(-1)
                continue

            # Check if elements are consecutive
            sorted_subarray = sorted(subarray)
            is_consecutive = True
            for j in range(1, k):
                if sorted_subarray[j] != sorted_subarray[j - 1] + 1:
                    is_consecutive = False
                    break

            if is_consecutive:
                result.append(max(subarray))
            else:
                result.append(-1)

        return result

class Solution:
    def maximumValueSum(self, board: List[List[int]]) -> int:
        n, m = len(board), len(board[0])
        # Create list of (value, row, col)
        cells = []
        for i in range(n):
            for j in range(m):
                cells.append((board[i][j], i, j))

        # Sort by value in descending order
        cells.sort(key=lambda x: x[0], reverse=True)

        max_sum = float('-inf')
        total_cells = len(cells)

        # Try all possible combinations of 3 rooks with distinct rows and columns
        # We'll iterate through all triplets of cells
        for i in range(total_cells):
            for j in range(i + 1, total_cells):
                for k in range(j + 1, total_cells):
                    # Check if the three selected cells have distinct rows and columns
                    row1, col1 = cells[i][1], cells[i][2]
                    row2, col2 = cells[j][1], cells[j][2]
                    row3, col3 = cells[k][1], cells[k][2]

                    # Check distinct rows and columns
                    if row1 != row2 and row1 != row3 and row2 != row3 and col1 != col2 and col1 != col3 and col2 != col3:
                        current_sum = cells[i][0] + cells[j][0] + cells[k][0]
                        max_sum = max(max_sum, current_sum)

        return max_sum if max_sum != float('-inf') else 0

