                count += 1
                if count >= 2:
                    return True
        return False

class Solution:
    def minNumberOfSeconds(self, mountainHeight: int, workerTimes: List[int]) -> int:
        def total_time_for_worker(worker_time, reduction):
            return worker_time * (reduction * (reduction + 1) // 2)

        def total_time_for_worker_with_reduction(worker_time, reduction):
            return worker_time * (reduction * (reduction + 1) // 2)

        # Binary search on the total time
        left, right = 0, mountainHeight * (mountainHeight + 1) // 2 * max(workerTimes) if workerTimes else 0

        # If only one worker, we need to compute the total time directly
        if len(workerTimes) == 1:
            return total_time_for_worker(workerTimes[0], mountainHeight)

        # Binary search for minimum time
        def can_reduce_in_time(total_time):
            # For each worker, compute how much height they can reduce in total_time
            # Height reduced by worker i = reduction such that workerTimes[i] * (1 + 2 + ... + k) <= total_time
            # So k*(k+1)/2 <= total_time / workerTimes[i]
            # k^2 + k - 2*total_time/workerTimes[i] <= 0
            # k <= (-1 + sqrt(1 + 8*total_time/workerTimes[i])) / 2
            total_reduction = 0
            for worker_time in workerTimes:
                # Solve k*(k+1)/2 <= total_time / worker_time
                # k^2 + k - 2*total_time/worker_time <= 0
                # k <= (-1 + sqrt(1 + 8*total_time/worker_time)) / 2
                if total_time == 0:
                    continue
                k = int((-1 + (1 + 8 * total_time / worker_time) ** 0.5) / 2)
                # k is the maximum reduction this worker can achieve
                # We need to ensure k*(k+1)//2 * worker_time <= total_time
                while k * (k + 1) // 2 * worker_time > total_time:
                    k -= 1
                total_reduction += k
            return total_reduction >= mountainHeight

        # Binary search for minimum time
        left, right = 0, mountainHeight * (mountainHeight + 1) // 2 * max(workerTimes)

        while left < right:
            mid = (left + right) // 2
            if can_reduce_in_time(mid):
                right = mid
            else:
                left = mid + 1

        return left

class Solution:
    def kthCharacter(self, k: int) -> str:
        pos = k
        result = 0

        while pos > 1:
            result += 1
            pos = (pos - 1) // 2 + 1

        # The final character is determined by the total shift
        # We start with 'a' and shift it result times
        # Each shift moves to the next character in alphabet (with z wrapping to a)
        # So we need to compute (result) mod 26, then add to 'a'
        return chr(ord('a') + result % 26)

class Solution:
    def countOfSubstrings(self, word: str, k: int) -> int:
        vowels = set('aeiou')
        n = len(word)
        count = 0

        # Check every possible substring
        for i in range(n):
            vowel_present = set()
            consonant_count = 0

            for j in range(i, n):
                char = word[j]
                if char in vowels:
                    vowel_present.add(char)
                else:
                    consonant_count += 1

                # Check if current substring has all vowels and exactly k consonants
                if len(vowel_present) == 5 and consonant_count == k:
                    count += 1

        return count

class Solution:
    def maxGoodNumber(self, nums: List[int]) -> int:
        def to_binary(n):
            return bin(n)[2:]

        def from_binary(s):
            return int(s, 2)

        # Generate all permutations of the three numbers
        from itertools import permutations

        max_result = 0
        for perm in permutations(nums):
            # Convert each number to binary string
            binary_strings = [to_binary(num) for num in perm]
            # Concatenate without leading zeros (already handled by bin)
            concatenated = ''.join(binary_strings)
            # Convert back to integer
            result = from_binary(concatenated)
            max_result = max(max_result, result)

        return max_result

class Solution:
    def gcdValues(self, nums: List[int], queries: List[int]) -> List[int]:
        from math import gcd
        from collections import Counter

        n = len(nums)
        total_pairs = n * (n - 1) // 2

        # For small arrays, generate all pairwise GCDs directly
        if n <= 20:
            gcd_pairs = []
            for i in range(n):
                for j in range(i + 1, n):
                    gcd_pairs.append(gcd(nums[i], nums[j]))
            gcd_pairs.sort()
            return [gcd_pairs[q] for q in queries]

        # For larger arrays, use frequency-based approach with Möbius inversion
        max_val = max(nums)

        # Count frequency of each number
        freq = [0] * (max_val + 1)
        for num in nums:
            if num <= max_val:
                freq[num] += 1

        # For each divisor d, count how many numbers are divisible by d
        div_count = [0] * (max_val + 1)
        for d in range(1, max_val + 1):
            for j in range(d, max_val + 1, d):
                div_count[d] += freq[j]

        # Compute Möbius function mu(n) for n from 1 to max_val
        mu = [1] * (max_val + 1)
        is_prime = [True] * (max_val + 1)
        primes = []

        for i in range(2, max_val + 1):
            if is_prime[i]:
                primes.append(i)
                mu[i] = -1
            for p in primes:
                if i * p > max_val:
                    break
                is_prime[i * p] = False
                if i % p == 0:
                    mu[i * p] = 0
                    break
                else:
                    mu[i * p] = -mu[i]

        # Count frequency of each GCD value using Möbius inversion
        gcd_freq = [0] * (max_val + 1)

        for g in range(1, max_val + 1):
            count = 0
            # Count pairs with GCD divisible by g
            pairs_divisible_by_g = div_count[g] * (div_count[g] - 1) // 2
            # Use Möbius inversion to get exact GCD count
            for k in range(1, (max_val // g) + 1):
                multiple = g * k
                if multiple > max_val:
                    break
                count += mu[k] * (div_count[multiple] * (div_count[multiple] - 1) // 2)
            gcd_freq[g] = count

