        gcd_values = []
        for g in range(1, max_val + 1):
            if gcd_freq[g] > 0:
                for _ in range(gcd_freq[g]):
                    gcd_values.append(g)

        # Answer queries
        result = []
        for q in queries:
            if q < len(gcd_values):
                result.append(gcd_values[q])
            else:
                result.append(0)

        return result

