class Solution:
    def minStartingIndex(self, s: str, pattern: str) -> int:
        n, m = len(s), len(pattern)
        min_index = float('inf')

        for i in range(n - m + 1):
            # Check if substring s[i:i+m] is almost equal to pattern
            diff_count = 0
            valid = True

            for j in range(m):
                if s[i + j] != pattern[j]:
                    diff_count += 1
                    if diff_count > 1:
                        valid = False
                        break

            if valid and diff_count <= 1:
                min_index = min(min_index, i)

        return min_index if min_index != float('inf') else -1

