class Solution:
    def countWinningSequences(self, s: str) -> int:
        MOD = 10**9 + 7
        n = len(s)

        # dp[i][last][diff] -> too expensive, use state (last_move, diff)
        # We'll use dictionary: key = (last_move, diff), value = count
        # At each position, we update based on Alice's current move

        dp = {(None, 0): 1}

        for i in range(n):
            next_dp = {}
            current_char = s[i]

            for (last_move, diff), count in dp.items():
                # Bob can choose any move except last_move
                for move in ['F', 'W', 'E']:
                    if move == last_move:
                        continue

                    # Calculate point difference based on Alice's move and Bob's move
                    if move == 'F':
                        if current_char == 'E':
                            # Bob's F vs Alice's E: Bob gets point
                            new_diff = diff + 1
                        elif current_char == 'W':
                            # Bob's F vs Alice's W: no point (W beats F)
                            new_diff = diff
                        else:  # current_char == 'F'
                            # Bob's F vs Alice's F: no point
                            new_diff = diff
                    elif move == 'W':
                        if current_char == 'F':
                            # Bob's W vs Alice's F: Bob gets point
                            new_diff = diff + 1
                        elif current_char == 'E':
                            # Bob's W vs Alice's E: no point (E beats W)
                            new_diff = diff
                        else:  # current_char == 'W'
                            # Bob's W vs Alice's W: no point
                            new_diff = diff
                    else:  # move == 'E'
                        if current_char == 'W':
                            # Bob's E vs Alice's W: Bob gets point
                            new_diff = diff + 1
                        elif current_char == 'F':
                            # Bob's E vs Alice's F: no point (F beats E)
                            new_diff = diff
                        else:  # current_char == 'E'
                            # Bob's E vs Alice's E: no point
                            new_diff = diff

                    # Only add if we haven't seen this state before, or add with count
                    key = (move, new_diff)
                    if key not in next_dp:
                        next_dp[key] = 0
                    next_dp[key] = (next_dp[key] + count) % MOD

            dp = next_dp

        # Sum all states where Bob's score > Alice's score (diff > 0)
        result = 0
        for (last_move, diff), count in dp.items():
            if diff > 0:
                result = (result + count) % MOD

        return result

