class Solution:
    def stringSequence(self, target: str) -> List[str]:
        result = []
        n = len(target)

        # Use BFS to generate strings in the correct order
        from collections import deque
        queue = deque([("", 0)])  # (current_string, next_index_to_match)
        seen = set()

        while queue:
            current_str, idx = queue.popleft()

            # Add to result if not seen
            if current_str not in seen:
                seen.add(current_str)
                result.append(current_str)

            # If we've matched the entire target, stop
            if idx == n:
                continue

            # Try appending 'a' (key 1)
            new_str = current_str + "a"
            if len(new_str) <= n:
                if new_str not in seen:
                    queue.append((new_str, idx + 1))

            # Try changing last character (key 2) - only if we can make progress
            if current_str:
                last_char = current_str[-1]
                next_char = chr(ord(last_char) + 1)
                if next_char <= 'z':
                    new_str = current_str[:-1] + next_char
                    if len(new_str) <= n:
                        if new_str not in seen:
                            queue.append((new_str, idx + 1))

        return result

