class Solution:
    def numberOfSubstrings(self, s: str, k: int) -> int:
        n = len(s)
        total = 0

        # For each possible substring length, count valid substrings
        for i in range(n):
            char_count = {}
            for j in range(i, n):
                char_count[s[j]] = char_count.get(s[j], 0) + 1
                # Check if any character appears at least k times
                if max(char_count.values()) >= k:
                    total += 1

        return total

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]

        # Build adjacency list
        for i in range(1, n):
            children[parent[i]].append(i)

        def dfs(node):
            result = []
            for child in children[node]:
                result.extend(dfs(child))
            result.append(s[node])
            return result

        def is_palindrome(arr):
            return arr == arr[::-1]

        answer = [False] * n

        for i in range(n):
            path = dfs(i)
            answer[i] = is_palindrome(path)

        return answer

