class Solution:
    def hasIncreasingSubarrays(self, nums: List[int], k: int) -> bool:
        n = len(nums)
        # Check each possible starting position for a subarray of length k
        for i in range(n - k):
            # Check if subarray starting at i is strictly increasing
            is_increasing = True
            for j in range(k - 1):
                if nums[i + j] >= nums[i + j + 1]:
                    is_increasing = False
                    break

            if not is_increasing:
                continue

            # Check if the subarray starting at i + k is strictly increasing
            # and they are adjacent (b = a + k)
            j = i + k
            if j + k <= n:
                is_increasing2 = True
                for idx in range(k - 1):
                    if nums[j + idx] >= nums[j + idx + 1]:
                        is_increasing2 = False
                        break

                if is_increasing2:
                    return True

        return False

class Solution:
    def minimumSumSubarray(self, nums: List[int], l: int, r: int) -> int:
        n = len(nums)
        min_sum = float('inf')

        # Check all subarrays with length between l and r (inclusive)
        for length in range(l, r + 1):
            # Use sliding window to get all subarrays of current length
            for i in range(n - length + 1):
                current_sum = sum(nums[i:i + length])
                # Only consider subarrays with positive sum
                if current_sum > 0:
                    min_sum = min(min_sum, current_sum)

        # Return -1 if no positive sum subarray found
        return min_sum if min_sum != float('inf') else -1

class Solution:
    def minBitwiseArray(self, nums: List[int]) -> List[int]:
        def find_min_ans(target):
            # For a given target, find the smallest x such that x OR (x+1) == target
            # We iterate from 0 upwards to find the minimal x
            x = 0
            while True:
                if x | (x + 1) == target:
                    return x
                # If we exceed reasonable bounds, return -1
                if x > target:
                    return -1
                x += 1

        result = []
        for num in nums:
            ans = find_min_ans(num)
            result.append(ans)

        return result

class Solution:
    def maxScore(self, n: int, k: int, stayScore: List[List[int]], travelScore: List[List[int]]) -> int:
        # dp[i][j] represents the maximum score achievable on day i ending at city j
        dp = [[0] * n for _ in range(k)]

        # Initialize first day: tourist can either stay or start at any city
        for j in range(n):
            dp[0][j] = stayScore[0][j]

        # For each day from 1 to k-1
        for day in range(1, k):
            # Option 1: Stay in current city
            for city in range(n):
                dp[day][city] = dp[day-1][city] + stayScore[day][city]

            # Option 2: Move from another city to current city
            for city in range(n):
                for prev_city in range(n):
                    # Move from prev_city to city on current day
                    if prev_city != city:
                        dp[day][city] = max(dp[day][city], dp[day-1][prev_city] + travelScore[prev_city][city])

        # Return maximum score across all cities on the last day
        return max(dp[k-1])

