class Solution:
    def smallestNumber(self, n: int, t: int) -> int:
        def digit_product(num):
            product = 1
            for digit in str(num):
                if digit == '0':
                    return 0
                product *= int(digit)
            return product

        current = n
        while True:
            product = digit_product(current)
            if product % t == 0:
                return current
            current += 1

class Solution:
    def maxCollectedFruits(self, fruits: List[List[int]]) -> int:
        n = len(fruits)
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(i1, j1, i2, j2, i3, j3):
            # Base case: if any child has reached (n-1, n-1)
            if i1 == n-1 and j1 == n-1:
                return 0
            if i2 == n-1 and j2 == n-1:
                return 0
            if i3 == n-1 and j3 == n-1:
                return 0

            # Check if any child is out of bounds
            if i1 >= n or j1 >= n or i2 >= n or j2 >= n or i3 >= n or j3 >= n:
                return 0
            if i1 < 0 or j1 < 0 or i2 < 0 or j2 < 0 or i3 < 0 or j3 < 0:
                return 0

            # Calculate fruits collected at current positions
            total = 0
            positions = [(i1, j1), (i2, j2), (i3, j3)]
            collected = set()

            for r, c in positions:
                if 0 <= r < n and 0 <= c < n:
                    if (r, c) not in collected:
                        collected.add((r, c))
                        total += fruits[r][c]

            # Try all possible moves for each child
            max_fruits = 0

            # Child 1: from (i1,j1) can go to (i1+1,j1+1), (i1+1,j1), (i1,j1+1)
            for di1, dj1 in [(1,1), (1,0), (0,1)]:
                ni1, nj1 = i1 + di1, j1 + dj1
                if ni1 < n and nj1 < n:
                    candidate = total + dp(ni1, nj1, i2, j2, i3, j3)
                    max_fruits = max(max_fruits, candidate)

            # Child 2: from (i2,j2) can go to (i2+1,j2-1), (i2+1,j2), (i2+1,j2+1)
            for di2, dj2 in [(1,-1), (1,0), (1,1)]:
                ni2, nj2 = i2 + di2, j2 + dj2
                if ni2 < n and 0 <= nj2 < n:
                    candidate = total + dp(i1, j1, ni2, nj2, i3, j3)
                    max_fruits = max(max_fruits, candidate)

            # Child 3: from (i3,j3) can go to (i3-1,j3+1), (i3, j3+1), (i3+1, j3+1)
            for di3, dj3 in [(-1,1), (0,1), (1,1)]:
                ni3, nj3 = i3 + di3, j3 + dj3
                if 0 <= ni3 < n and 0 <= nj3 < n:
                    candidate = total + dp(i1, j1, i2, j2, ni3, nj3)
                    max_fruits = max(max_fruits, candidate)

            return max_fruits

        # Start from initial positions
        return dp(0, 0, 0, n-1, n-1, 0)

