class Solution:
    def getLargestOutlier(self, nums: List[int]) -> int:
        n = len(nums)
        max_outlier = float('-inf')

        # Try each element as the sum of the special numbers
        for sum_val in nums:
            # Create a list of remaining elements after removing sum_val
            remaining = [x for x in nums if x != sum_val]

            # We need exactly n-1 elements left (since we remove sum_val)
            if len(remaining) != n - 1:
                continue

            # Try each element in remaining as the outlier
            for outlier in remaining:
                # The rest should be n-3 elements that sum to sum_val
                rest = [x for x in remaining if x != outlier]
                if len(rest) == n - 3 and sum(rest) == sum_val:
                    max_outlier = max(max_outlier, outlier)

        return max_outlier

