class Solution:
    def constructTransformedArray(self, nums: List[int]) -> List[int]:
        n = len(nums)
        result = [0] * n

        for i in range(n):
            if nums[i] == 0:
                result[i] = 0
            elif nums[i] > 0:
                # Move nums[i] steps to the right in circular array
                step = nums[i]
                new_index = (i + step) % n
                result[i] = nums[new_index]
            else:
                # Move abs(nums[i]) steps to the left in circular array
                step = abs(nums[i])
                new_index = (i - step) % n
                result[i] = nums[new_index]

        return result

class Solution:
    def maxRectangleArea(self, points: List[List[int]]) -> int:
        if len(points) < 4:
            return -1

        # Group points by x and y coordinates
        x_coords = sorted(set(p[0] for p in points))
        y_coords = sorted(set(p[1] for p in points))

        # Try all possible rectangles with edges parallel to axes
        max_area = -1

        for i in range(len(x_coords)):
            for j in range(i + 1, len(x_coords)):
                for k in range(len(y_coords)):
                    for l in range(k + 1, len(y_coords)):
                        # Form rectangle with corners (x_coords[i], y_coords[k]), (x_coords[j], y_coords[k]), (x_coords[i], y_coords[l]), (x_coords[j], y_coords[l])
                        x1, x2 = x_coords[i], x_coords[j]
                        y1, y2 = y_coords[k], y_coords[l]

                        # Check if all four corners are in points and no other point lies inside or on border
                        corners = [(x1, y1), (x1, y2), (x2, y1), (x2, y2)]
                        valid = True
                        for (cx, cy) in points:
                            # Check if point lies inside or on border of rectangle
                            if (x1 < cx < x2 or cx == x1 or cx == x2) and (y1 < cy < y2 or cy == y1 or cy == y2):
                                valid = False
                                break

                        if valid and (x2 - x1) * (y2 - y1) > max_area:
                            max_area = (x2 - x1) * (y2 - y1)

        return max_area

