class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        if k == 1:
            return sum(nums)

        max_sum = float('-inf')
        # Try all subarrays of length divisible by k
        for i in range(0, n - k + 1, k):
            length = k
            current_sum = 0
            for j in range(i, i + length):
                current_sum += nums[j]
            max_sum = max(max_sum, current_sum)

        # Also check subarrays of length 2k, 3k, etc.
        for length in range(k, n + 1, k):
            if length > n:
                break
            # Use sliding window to find max sum of subarray of given length
            current_sum = sum(nums[:length])
            max_sum = max(max_sum, current_sum)
            if length == n:
                break
            for i in range(1, n - length + 1):
                current_sum = current_sum - nums[i - 1] + nums[i + length - 1]
                max_sum = max(max_sum, current_sum)

        return max_sum if max_sum != float('-inf') else 0

