class Solution:
    def findMinimumTime(self, strength: List[int], K: int) -> int:
        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(mask, x):
            if mask == 0:
                return 0

            min_time = float('inf')
            # Try breaking each lock that hasn't been broken yet
            for i in range(len(strength)):
                if not (mask & (1 << i)):
                    continue
                # Check if we can break lock i at current energy level
                # Energy at time t is: x + (x+1) + (x+2) + ... + (x + t - 1) = t*x + t*(t-1)/2
                # We need: t*x + t*(t-1)/2 >= strength[i]
                # We want minimum t such that this holds
                # This is equivalent to: t*(x + (t-1)/2) >= strength[i]
                # We can solve for t using binary search
                left, right = 0, strength[i] * 2
                while left < right:
                    mid = (left + right) // 2
                    energy = mid * x + mid * (mid - 1) // 2
                    if energy >= strength[i]:
                        right = mid
                    else:
                        left = mid + 1
                t = left

                # After breaking lock i, x increases by K
                new_x = x + K
                new_mask = mask & ~(1 << i)
                time = t + dp(new_mask, new_x)
                min_time = min(min_time, time)

            return min_time if min_time != float('inf') else 0

        # Start with all locks unbroken, initial x = 1
        return dp((1 << len(strength)) - 1, 1)

