class Solution:
    def minOperations(self, n: int, m: int) -> int:
        def is_prime(x):
            if x < 2:
                return False
            if x == 2:
                return True
            if x % 2 == 0:
                return False
            for i in range(3, int(x**0.5) + 1, 2):
                if x % i == 0:
                    return False
            return True

        # If m is prime, we can't reach it
        if is_prime(m):
            return -1

        # If n is already m, cost is 0
        if n == m:
            return 0

        # We need to transform n to m without passing through any prime number
        # We can only increase non-9 digits or decrease non-0 digits

        # BFS to find minimum cost
        from collections import deque

        # Convert to strings for digit manipulation
        n_str = str(n)
        m_str = str(m)

        # Check if transformation is possible
        # We can only go through non-prime numbers

        # We'll use BFS with state (current_number, cost)
        queue = deque([(n, 0)])
        visited = {n}

        while queue:
            curr, cost = queue.popleft()

            # Convert current number to string for digit manipulation
            curr_str = str(curr)

            # Try all possible next states
            # We can increase any non-9 digit by 1, or decrease any non-0 digit by 1

            # Generate next states
            next_states = []

            # Try increasing each digit
            for i in range(len(curr_str)):
                if curr_str[i] != '9':
                    new_digits = list(curr_str)
                    new_digits[i] = str(int(new_digits[i]) + 1)
                    new_num = int(''.join(new_digits))
                    if new_num != curr and new_num not in visited:
                        # Check if new_num is prime
                        if not is_prime(new_num):
                            next_states.append(new_num)

            # Try decreasing each digit
            for i in range(len(curr_str)):
                if curr_str[i] != '0':
                    new_digits = list(curr_str)
                    new_digits[i] = str(int(new_digits[i]) - 1)
                    new_num = int(''.join(new_digits))
                    if new_num != curr and new_num not in visited:
                        # Check if new_num is prime
                        if not is_prime(new_num):
                            next_states.append(new_num)

            # Check if we reached m
            for next_val in next_states:
                if next_val == m:
                    return cost + 1

                if next_val not in visited:
                    visited.add(next_val)
                    queue.append((next_val, cost + 1))

        # If we can't reach m
        return -1

