class Solution:
    def minimumOperations(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 3:
            # If array has 0, 1, 2, or 3 elements, check if they are distinct
            return 0 if len(set(nums)) == len(nums) else 1

        # We'll simulate the removal process
        # Keep removing groups of 3 from the beginning until all elements are distinct
        remaining = nums[:]
        operations = 0

        while len(remaining) > 0:
            # Check if current array has distinct elements
            if len(set(remaining)) == len(remaining):
                break

            # Remove first 3 elements
            if len(remaining) >= 3:
                remaining = remaining[3:]
            else:
                # Less than 3 elements left, remove all
                remaining = []

            operations += 1

        return operations

