    def countPathsWithXorValue(self, grid: List[List[int]], k: int) -> int:
        m, n = len(grid), len(grid[0])
        MOD = 10**9 + 7

        # dp[i][j][xor] = number of paths from (0,0) to (i,j) with XOR value = xor
        # We only need the previous row, so we optimize space
        from collections import defaultdict

        # Use dictionary to store states for current row
        # Key: (row, col), Value: dict of xor -> count
        # We'll iterate row by row

        # Start with (0,0) with xor = grid[0][0]
        prev = {(0, 0): {grid[0][0]: 1}}

        for i in range(m):
            curr = {}
            for j in range(n):
                if i == 0 and j == 0:
                    continue

                # Initialize current state
                state = defaultdict(int)

                # From left (same row)
                if j > 0:
                    # From (i, j-1)
                    for prev_xor, count in prev.get((i, j-1), {}).items():
                        new_xor = prev_xor ^ grid[i][j]
                        state[new_xor] = (state[new_xor] + count) % MOD

                # From above (same column)
                if i > 0:
                    # From (i-1, j)
                    for prev_xor, count in prev.get((i-1, j), {}).items():
                        new_xor = prev_xor ^ grid[i][j]
                        state[new_xor] = (state[new_xor] + count) % MOD

                # Store current state
                if (i, j) not in curr:
                    curr[(i, j)] = state
                else:
                    curr[(i, j)] = state

                # Update prev for next iteration
                prev = curr

            # If we're at the last row and last column, check if final xor equals k
            if i == m - 1 and j == n - 1:
                return state.get(k, 0) % MOD

        # If we reach here, we need to check the final state
        if (m-1, n-1) in prev:
            return prev[(m-1, n-1)].get(k, 0) % MOD

        return 0

