class Solution:
    def maxLength(self, nums: List[int]) -> int:
        from math import gcd, lcm
        from functools import reduce

        def product(arr):
            result = 1
            for num in arr:
                result *= num
            return result

        def gcd_of_array(arr):
            return reduce(gcd, arr)

        def lcm_of_array(arr):
            result = 1
            for num in arr:
                result = lcm(result, num)
            return result

        n = len(nums)
        max_length = 0

        # Check all possible subarrays
        for i in range(n):
            for j in range(i, n):
                subarray = nums[i:j+1]
                prod_val = product(subarray)
                g = gcd_of_array(subarray)
                l = lcm_of_array(subarray)
                if prod_val == g * l:
                    max_length = max(max_length, j - i + 1)

        return max_length

