    def maximumWeight(self, intervals: List[List[int]]) -> List[int]:
        # Sort intervals by end position, then by weight (descending) to prioritize non-overlapping
        intervals.sort(key=lambda x: (x[1], -x[2]))

        # Try all combinations of up to 4 non-overlapping intervals
        n = len(intervals)
        best_score = 0
        best_selection = []

        # Generate all possible combinations of up to 4 intervals
        from itertools import combinations

        # Try all possible subsets of size 0 to 4
        for r in range(0, 5):
            for indices in combinations(range(n), r):
                # Check if intervals at these indices are non-overlapping
                selected = []
                selected_intervals = []
                for idx in indices:
                    selected_intervals.append(intervals[idx])

                # Check for overlaps among selected intervals
                valid = True
                for i in range(len(selected_intervals)):
                    for j in range(i + 1, len(selected_intervals)):
                        if selected_intervals[i][0] <= selected_intervals[j][1] or selected_intervals[j][0] <= selected_intervals[i][1]:
                            valid = False
                            break
                    if not valid:
                        break

                if not valid:
                    continue

                # Calculate total weight
                total_weight = sum(intervals[idx][2] for idx in indices)

                # Update best selection if this one is better
                if total_weight > best_score:
                    best_score = total_weight
                    best_selection = list(indices)
                elif total_weight == best_score:
                    # If same score, choose lexicographically smaller array
                    current = list(indices)
                    if current < best_selection:
                        best_selection = current

        # Convert indices to the original array indices
        result = []
        for idx in best_selection:
            result.append(idx)

        return result

