class Solution:
    def hasMatch(self, s: str, p: str) -> bool:
        star_index = p.find('*')
        if star_index == -1:
            return p == s

        # Split pattern into two parts: before and after star
        prefix = p[:star_index]
        suffix = p[star_index + 1:]

        # Try all possible positions where the star can match in s
        n = len(s)
        for i in range(n + 1):
            # Check if prefix matches s[0:i]
            if self.match_prefix(prefix, s[:i]):
                # Check if suffix matches s[i:n]
                if self.match_suffix(suffix, s[i:]):
                    return True

        return False

    def match_prefix(self, pattern, string):
        if len(pattern) == 0:
            return True
        if len(string) == 0:
            return False

        # Check if pattern matches the beginning of string
        i = 0
        j = 0
        while j < len(string):
            if i < len(pattern) and pattern[i] == string[j]:
                i += 1
                j += 1
            elif i < len(pattern) and pattern[i] == '*':
                # Star can match zero or more characters
                # We'll handle this by recursively checking if suffix matches
                # But since we're already in prefix/suffix logic, we'll just use direct matching
                break
            else:
                return False

        # If we've matched all of pattern except for star, we need to check if rest matches
        # But since we're using prefix/suffix split, we just need to check if pattern matches
        # until star, then star can match any substring
        # So we just check if prefix matches the beginning
        return i == len(pattern) and (pattern[i] == '*' or i == len(pattern))

    def match_suffix(self, pattern, string):
        if len(pattern) == 0:
            return True
        if len(string) == 0:
            return False

        # Check if pattern matches the end of string
        i = 0
        j = len(string) - 1
        while i < len(pattern) and j >= 0:
            if i < len(pattern) and pattern[i] == string[j]:
                i += 1
                j -= 1
            elif i < len(pattern) and pattern[i] == '*':
                # Star can match zero or more characters
                # We need to check if the rest of the pattern matches the remaining string
                # But since we're handling this in the main logic, we just check if pattern matches
                # from start to end
                break
            else:
                return False

        # If we've matched all of pattern except for star, we need to check if rest matches
        # But since we're using prefix/suffix split, we just need to check if suffix matches
        # So we check if pattern matches from start to end
        return i == len(pattern) and (pattern[i] == '*' or i == len(pattern))

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        # We'll use dynamic programming with state: 
        # For each value, we maintain a dictionary mapping last difference to maximum length
        # We iterate through the array and update the DP state

        # dp[value] = dictionary: last_diff -> max_length for subsequences ending at value
        from collections import defaultdict

        # We'll maintain: dp[value] = dict of (last_diff -> max_length)
        dp = defaultdict(dict)

        max_length = 1

        for i in range(n):
            current_val = nums[i]

            # Start a new subsequence of length 1
            dp[current_val][0] = 1
            max_length = max(max_length, 1)

            # Try to extend from previous values
            for prev_val in dp:
                if prev_val == current_val:
                    # Same value, difference is 0
                    # We can extend if we already have a subsequence ending with this value
                    # But we can only extend if we have a non-zero last difference or if we can extend with 0
                    # Actually, we can extend with 0 difference
                    if 0 not in dp[prev_val]:
                        dp[prev_val][0] = 1
                    # We can extend with 0 difference
                    new_len = dp[prev_val][0] + 1
                    if 0 not in dp[current_val]:
                        dp[current_val][0] = new_len
                    else:
                        dp[current_val][0] = max(dp[current_val][0], new_len)
                else:
                    diff = abs(current_val - prev_val)
                    # We can extend from prev_val to current_val if diff >= last_diff
                    for last_diff, length in dp[prev_val].items():
                        if diff >= last_diff:
                            new_len = length + 1
                            if diff not in dp[current_val]:
                                dp[current_val][diff] = new_len
                            else:
                                dp[current_val][diff] = max(dp[current_val][diff], new_len)

            # Update max_length
            for diff, length in dp[current_val].items():
                max_length = max(max_length, length)

        return max_length

class Solution:
    def longestSubsequence(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 0:
            return 0

        from collections import defaultdict

        # dp[val] will store the maximum length of subsequence ending at val with each possible last difference
        # We use: dp[val][diff] = max_length ending at val with last difference = diff
        dp = defaultdict(dict)
        max_length = 1

        for i in range(n):
            current_val = nums[i]

            # Start new subsequence of length 1
            dp[current_val][0] = 1
            max_length = max(max_length, 1)

            # Try to extend from previous values
            for prev_val in dp:
                if prev_val == current_val:
                    # Same value, difference is 0
                    # We can extend from any subsequence ending at prev_val
                    # We want to extend with difference 0
                    new_len = dp[prev_val][0] + 1
                    if 0 not in dp[current_val]:
                        dp[current_val][0] = new_len
                    else:
                        dp[current_val][0] = max(dp[current_val][0], new_len)
                else:
                    diff = abs(current_val - prev_val)
                    # We can extend from prev_val to current_val if diff >= last_diff
                    for last_diff, length in dp[prev_val].items():
                        if diff >= last_diff:
                            new_len = length + 1
                            if diff not in dp[current_val]:
                                dp[current_val][diff] = new_len
                            else:
                                dp[current_val][diff] = max(dp[current_val][diff], new_len)

            # Update max_length from current state
            for length in dp[current_val].values():
                max_length = max(max_length, length)

        return max_length

class Solution:
    def maxSubarraySum(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]

        # Calculate maximum subarray sum without any removal
        max_sum = self.kadane(nums)

        # Try removing each unique element and find maximum subarray sum
        from collections import Counter
        count = Counter(nums)

        # Try removing each unique element
        for x in count:
            # Compute Kadane's sum after removing all occurrences of x
            current_sum = 0
            max_current = 0
            for num in nums:
                if num != x:
                    current_sum = max(num, current_sum + num)
                    max_current = max(max_current, current_sum)

            max_sum = max(max_sum, max_current)

        return max_sum

    def kadane(self, arr):
        if not arr:
            return 0

        max_sum = current_sum = arr[0]
        for i in range(1, len(arr)):
            current_sum = max(arr[i], current_sum + arr[i])
            max_sum = max(max_sum, current_sum)

        return max_sum

