class Solution:
    def zigzagTraversal(self, grid: List[List[int]]) -> List[int]:
        result = []
        m, n = len(grid), len(grid[0])

        for i in range(m):
            if i % 2 == 0:
                # Even row index: traverse right (normal direction)
                for j in range(n):
                    result.append(grid[i][j])
            else:
                # Odd row index: traverse left (reverse direction)
                for j in range(n - 1, -1, -1):
                    result.append(grid[i][j])

        return result

