class Solution:
    def subarraySum(self, nums: List[int]) -> int:
        total_sum = 0
        n = len(nums)

        for i in range(n):
            start = max(0, i - nums[i])
            subarray_sum = sum(nums[start:i+1])
            total_sum += subarray_sum

        return total_sum

class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0

        # Consider all subarrays of length 1 to k
        for i in range(n):
            for j in range(i, min(i + k, n)):
                subarray = nums[i:j+1]
                min_val = min(subarray)
                max_val = max(subarray)
                total += min_val + max_val

        return total

class Solution:
    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # Initialize mentions array with zeros for each user
        mentions = [0] * numberOfUsers

        # Track online status of users (True = online, False = offline)
        online = [True] * numberOfUsers

        # Sort events by timestamp to process them in chronological order
        sorted_events = sorted(events, key=lambda x: int(x[1]))

        for event in sorted_events:
            event_type = event[0]
            timestamp = int(event[1])
            if event_type == "OFFLINE":
                user_id = int(event[2])
                # Mark user as offline for next 60 time units
                # We don't need to track exact time intervals, just status at event time
                online[user_id] = False
            else:  # MESSAGE event
                # Parse the mentions string
                mentions_str = event[2]

                # Handle "ALL" case - mention all users
                if mentions_str == "ALL":
                    for i in range(numberOfUsers):
                        if online[i]:
                            mentions[i] += 1
                # Handle "HERE" case - mention only online users
                elif mentions_str == "HERE":
                    for i in range(numberOfUsers):
                        if online[i]:
                            mentions[i] += 1
                else:
                    # Parse id<number> tokens
                    ids = mentions_str.split()
                    for id_str in ids:
                        if id_str.startswith("id"):
                            user_id = int(id_str[2:])
                            # Count each mention separately even if duplicate
                            mentions[user_id] += 1

        return mentions

