class Solution:
    def maxDifference(self, s: str) -> int:
        freq = {}
        for char in s:
            freq[char] = freq.get(char, 0) + 1

        odd_freq = []
        even_freq = []

        for char, count in freq.items():
            if count % 2 == 0:
                even_freq.append(count)
            else:
                odd_freq.append(count)

        if odd_freq and even_freq:
            return max(odd_freq) - min(even_freq)
        elif odd_freq:
            return odd_freq[0] - 0  # This shouldn't happen per constraints
        else:
            return 0  # This shouldn't happen per constraints

class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        nums.sort()
        result = 0
        n = len(nums)
        m = len(target)

        # For each target value, find the smallest multiple of any nums[i] that is >= target[j]
        # We can use a greedy approach: for each target value, find the minimum cost to make it a multiple of any nums[i]

        for t in target:
            min_cost = float('inf')
            for num in nums:
                # Find the smallest multiple of num that is >= t
                # It's ceil(t / num) * num
                if t % num == 0:
                    cost = 0
                else:
                    cost = ((t // num) + 1) * num - t
                min_cost = min(min_cost, cost)
            result += min_cost

        return result

