                top_right_diagonals.append(diagonal)

        # Sort bottom-left diagonals in non-increasing order
        bottom_left_diagonals_sorted = []
        for diag in bottom_left_diagonals:
            sorted_diag = sorted(diag, reverse=True)
            bottom_left_diagonals_sorted.append(sorted_diag)

        # Sort top-right diagonals in non-decreasing order
        top_right_diagonals_sorted = []
        for diag in top_right_diagonals:
            sorted_diag = sorted(diag)
