        # Reconstruct the matrix
        result = [[0] * n for _ in range(n)]

        # Fill bottom-left diagonals
        idx = 0
        for i in range(n):
            for j in range(n):
                if i + j >= n - 1:
                    result[i][j] = bottom_left_diagonals_sorted[idx][0]
                    idx += 1

        # Fill top-right diagonals
        idx = 0
        for i in range(n):
            for j in range(n):
                if i + j < n - 1:
                    result[i][j] = top_right_diagonals_sorted[idx][0]
                    idx += 1

        return result

