    def assignElements(self, groups: List[int], elements: List[int]) -> List[int]:
        n, m = len(groups), len(elements)
        assigned = [-1] * n

        # For each element, find all groups that it can be assigned to
        # We prioritize smaller indices for elements
        for j in range(m):
            element = elements[j]
            # Assign this element to all groups that are divisible by element
            # We only assign if the group hasn't been assigned yet
            for i in range(n):
                if groups[i] % element == 0 and assigned[i] == -1:
                    assigned[i] = j

        return assigned

class Solution:
    def countSubstrings(self, s: str) -> int:
        n = len(s)
        total = 0

        # Count all substrings that end with a non-zero digit and are divisible by that digit
        for i in range(n):
            for j in range(i, n):
                # Extract substring from i to j (inclusive)
                substring = s[i:j+1]
                last_digit = int(s[j])

                # Skip if last digit is zero
                if last_digit == 0:
                    continue

                # Convert substring to integer
                num = int(substring)

                # Check if divisible by last digit
                if num % last_digit == 0:
                    total += 1

        return total

class Solution:
