        n = len(s)
        total = 0

        # Count all substrings that end with a non-zero digit and are divisible by that digit
        for i in range(n):
            current_sum = 0
            for j in range(i, n):
                # Add digit at j to current_sum (as a number)
                digit = int(s[j])
                # Update current_sum: current_sum = current_sum * 10 + digit
                current_sum = current_sum * 10 + digit

                # Skip if last digit is zero
                if digit == 0:
                    continue

                # Check if current_sum is divisible by digit
                if current_sum % digit == 0:
                    total += 1

