class Solution:
    def hasSpecialSubstring(self, s: str, k: int) -> bool:
        n = len(s)
        # Check each possible substring of length k
        for i in range(n - k + 1):
            substring = s[i:i + k]

            # Check if substring has only one distinct character
            if len(set(substring)) != 1:
                continue

            char = substring[0]

            # Check if character before substring is different (if exists)
            before_different = True
            if i > 0 and s[i - 1] == char:
                before_different = False

            # Check if character after substring is different (if exists)
            after_different = True
            if i + k < n and s[i + k] == char:
                after_different = False

            # If both conditions are met, return True
            if before_different and after_different:
                return True

        return False

class Solution:
    def hasSameDigits(self, s: str) -> bool:
        while len(s) > 2:
            new_s = ""
            for i in range(len(s) - 1):
                new_s += str((int(s[i]) + int(s[i + 1])) % 10)
            s = new_s
        return s[0] == s[1]

class Solution:
    def largestInteger(self, nums: List[int], k: int) -> int:
        n = len(nums)
        # Count how many subarrays of size k contain each integer
        count = {}

        # Iterate through all subarrays of size k
        for i in range(n - k + 1):
            subarray = nums[i:i + k]
            for num in subarray:
                count[num] = count.get(num, 0) + 1

        # Find all integers that appear in exactly one subarray
        candidates = []
        for num, freq in count.items():
            if freq == 1:
                candidates.append(num)

        # Return the largest such integer, or -1 if none exists
        return max(candidates) if candidates else -1

