class Solution:
    def longestPalindromicSubsequence(self, s: str, k: int) -> int:
        n = len(s)
        # dp[i][j] represents the length of longest palindromic subsequence in s[i:j+1]
        # We'll use a different approach: for each possible pair of indices, calculate min operations needed
        # and use DP with memoization

        def min_operations(c1, c2):
            # return minimum operations to make c1 equal to c2
            diff = abs(ord(c1) - ord(c2))
            return min(diff, 26 - diff)

        # For each possible length, check if we can form palindrome
        # We'll use DP: dp[i][j] = max length of palindromic subsequence in s[i:j+1]
        # with at most k operations

        # We can use a different approach: for each pair (i, j), compute min operations to make s[i] == s[j]
        # and if that is <= k, then we can extend palindrome

        # We'll use DP with state (left, right) and track cost
        memo = {}

        def dp(left, right):
            if left > right:
                return 0
            if left == right:
                return 1
            if (left, right) in memo:
                return memo[(left, right)]

            # Option 1: skip left character
            result = dp(left + 1, right)
            # Option 2: skip right character  
            result = max(result, dp(left, right - 1))

            # Option 3: use both ends (if they can be made equal with <= k operations)
            cost = min_operations(s[left], s[right])
            if cost <= k:
                result = max(result, 2 + dp(left + 1, right - 1))

            memo[(left, right)] = result
            return result

        return dp(0, n - 1)

