class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n, m = len(str1), len(str2)
        total_len = n + m - 1

        # If the total length is less than m, it's impossible
        if total_len < m:
            return ""

        # We'll build the result string greedily from left to right
        result = ['a'] * total_len

        # We'll go through each position in the result string
        for i in range(total_len):
            # Try to assign 'a' at position i
            # But we need to check if this assignment violates any constraint

            # Check if assigning 'a' at position i violates any constraint
            valid = True
            for j in range(n):
                start = j
                if start + m > total_len:
                    continue

                # Check constraint at position j
                if str1[j] == 'T':
                    # The substring from start to start + m - 1 must equal str2
                    substring = ''.join(result[start:start + m])
                    if substring != str2:
                        # We need to find a different character
                        # But we can't easily backtrack - we need to find the minimal character
                        # that satisfies all constraints
                        valid = False
                        break
                else:  # str1[j] == 'F'
                    # The substring from start to start + m - 1 must not equal str2
                    substring = ''.join(result[start:start + m])
                    if substring == str2:
                        valid = False
                        break

            # If assigning 'a' at position i doesn't violate any constraint, we keep it
            # Otherwise, we need to find a different character
            # We'll try to find the smallest character that doesn't violate any constraint
            if not valid:
                # We need to find a different character at position i
                # Try characters from 'a' to 'z'
                for c in range(ord('a'), ord('z') + 1):
                    result[i] = chr(c)
                    # Check if this assignment satisfies all constraints
                    valid = True
                    for j in range(n):
                        start = j
                        if start + m > total_len:
                            continue
                        substring = ''.join(result[start:start + m])
                        if str1[j] == 'T':
                            if substring != str2:
                                valid = False
                                break
                        else:
                            if substring == str2:
                                valid = False
                                break
                    if valid:
                        break
                else:
                    # No valid character found
                    return ""
            else:
                # 'a' is valid, so we keep it
                pass

        # Final validation: check if all constraints are satisfied
        for j in range(n):
            start = j
            if start + m > total_len:
                continue
            substring = ''.join(result[start:start + m])
            if str1[j] == 'T':
                if substring != str2:
                    return ""
            else:
                if substring == str2:
                    return ""

        return ''.join(result)

class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        # Create a list to track which baskets are used
        used = [False] * n

        unplaced = 0

        # For each fruit type, try to place it in the leftmost available basket with sufficient capacity
        for i in range(n):
            fruit_qty = fruits[i]
            # Look for the leftmost available basket with capacity >= fruit_qty
            for j in range(n):
                if not used[j] and baskets[j] >= fruit_qty:
                    used[j] = True
                    break
            else:
                # No basket found for this fruit type
                unplaced += 1

        return unplaced

