class Solution:
    def solveQueries(self, nums: List[int], queries: List[int]) -> List[int]:
        n = len(nums)
        # Group indices by value
        value_to_indices = {}
        for i, val in enumerate(nums):
            if val not in value_to_indices:
                value_to_indices[val] = []
            value_to_indices[val].append(i)

        result = []

        for query_idx in queries:
            val = nums[query_idx]
            indices = value_to_indices.get(val, [])

            if len(indices) == 1:
                result.append(-1)
            else:
                # Find the closest index to query_idx
                min_dist = float('inf')
                for idx in indices:
                    if idx == query_idx:
                        continue
                    # Calculate circular distance
                    dist1 = abs(query_idx - idx)
                    dist2 = (n - abs(query_idx - idx))
                    min_dist = min(min_dist, min(dist1, dist2))
                result.append(min_dist)

        return result

class Solution:
    def minZeroArray(self, nums: List[int], queries: List[List[int]]) -> int:
        n = len(nums)
        # Create a copy of nums to simulate the operations
        arr = nums[:]

        # Process queries one by one
        for i, (l, r, val) in enumerate(queries):
            # Decrement values in range [l, r] by val
            for j in range(l, r + 1):
                arr[j] -= val
                # If value becomes negative, it's impossible to reach zero array
                if arr[j] < 0:
                    return -1

        # Check if the array is all zeros
        if all(x == 0 for x in arr):
            return i + 1
        else:
            return -1

