    def beautifulNumbers(self, l: int, r: int) -> int:
        def is_beautiful(n):
            digits = [int(d) for d in str(n)]
            digit_product = 1
            digit_sum = 0

            for digit in digits:
                digit_product *= digit
                digit_sum += digit

            return digit_product % digit_sum == 0 if digit_sum != 0 else False

        count = 0
        for i in range(l, r + 1):
            if is_beautiful(i):
                count += 1

        return count

