class Solution:
    def maxContainers(self, n: int, w: int, maxWeight: int) -> int:
        total_cells = n * n
        total_weight = total_cells * w

        # If total weight exceeds maxWeight, we need to find maximum containers we can fit
        if total_weight <= maxWeight:
            return total_cells

        # We can't fit all containers, so we need to find maximum number of containers
        # that can be loaded without exceeding maxWeight
        max_containers = maxWeight // w

        # We can't load more containers than the total cells available
        return min(max_containers, total_cells)

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        if n == 0:
            return 0

        # Function to compute intersection size between two arrays
        def intersect(a, b):
            return len(set(a) & set(b))

        # Build adjacency list for the graph
        graph = [[] for _ in range(n)]

        for i in range(n):
            for j in range(i + 1, n):
                if intersect(properties[i], properties[j]) >= k:
                    graph[i].append(j)
                    graph[j].append(i)

        # Use DFS to count connected components
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                components += 1
                # DFS to mark all nodes in this component as visited
                stack = [i]
                while stack:
                    node = stack.pop()
                    if not visited[node]:
                        visited[node] = True
                        for neighbor in graph[node]:
                            if not visited[neighbor]:
                                stack.append(neighbor)

        return components

