        # Try all possible substrings from s and t
        for i in range(len(s) + 1):
            for j in range(len(t) + 1):
                # Try all possible substrings from s starting at i
                for k in range(i, len(s) + 1):
                    # Try all possible substrings from t starting at j
                    for l in range(j, len(t) + 1):
                        # Extract substrings
                        sub_s = s[i:k]
                        sub_t = t[j:l]

                        # Concatenate and check if palindrome
                        candidate = sub_s + sub_t
                        if candidate == candidate[::-1]:
                            max_length = max(max_length, len(candidate))

        # If no valid palindrome found, return 1 (single character)
        return max_length if max_length > 0 else 1

class Solution:
    def minimumPairRemoval(self, nums: List[int]) -> int:
        n = len(nums)
        if n <= 1:
            return 0

        # Create a copy of nums to work with
        arr = nums[:]
        operations = 0

        while True:
            # Find the adjacent pair with minimum sum
            min_sum = float('inf')
            min_idx = -1

            for i in range(n - 1):
                if arr[i] + arr[i + 1] < min_sum:
                    min_sum = arr[i] + arr[i + 1]
                    min_idx = i

            # If no pair found (array is already non-decreasing), break
            if min_idx == -1:
                break

            # Replace the pair with their sum
            arr[min_idx] = arr[min_idx] + arr[min_idx + 1]
            arr.pop(min_idx + 1)
            n -= 1
            operations += 1

            # Check if array is non-decreasing
            is_non_decreasing = True
            for i in range(1, len(arr)):
                if arr[i] < arr[i - 1]:
                    is_non_decreasing = False
                    break

            if is_non_decreasing:
                break

        return operations

