class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        from itertools import combinations

        n = len(nums)
        best_product = -1

        # Try all possible subsequences
        for r in range(1, n + 1):
            for subset in combinations(range(n), r):
                # Build the subsequence
                subseq = [nums[i] for i in subset]

                # Calculate alternating sum
                alt_sum = 0
                for i, val in enumerate(subseq):
                    if i % 2 == 0:
                        alt_sum += val
                    else:
                        alt_sum -= val

                # Check if alternating sum matches k
                if alt_sum != k:
                    continue

                # Calculate product
                product = 1
                for val in subseq:
                    product *= val

                # Check if product is within limit
                if product > limit:
                    continue

                # Update best product
                best_product = max(best_product, product)

        return best_product

