class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        MOD = 10**9 + 7

        total_cells = m * n

        # Precompute nCr mod MOD up to total_cells
        max_n = total_cells
        fact = [1] * (max_n + 1)
        for i in range(1, max_n + 1):
            fact[i] = (fact[i-1] * i) % MOD

        def mod_inverse(a, mod):
            return pow(a, mod - 2, mod)

        def nCr(n, r):
            if r < 0 or r > n:
                return 0
            if r == 0:
                return 1
            return (fact[n] * mod_inverse(fact[r], MOD) % MOD * mod_inverse(fact[n - r], MOD)) % MOD

        # Total arrangements containing any specific pair of cells
        arrangements_with_pair = nCr(total_cells - 2, k - 2)

        # Compute sum of |r1 - r2| over all unordered pairs of distinct cells
        row_sum = 0
        for i in range(m):
            for j in range(m):
                if i != j:
                    row_diff = abs(i - j)
                    # Each row pair (i,j) has n cells in each row, so n*n pairs
                    row_sum = (row_sum + row_diff * n * n) % MOD

        # Compute sum of |c1 - c2| over all unordered pairs of distinct cells
        col_sum = 0
        for i in range(n):
            for j in range(n):
                if i != j:
                    col_diff = abs(i - j)
                    # Each column pair (i,j) has m cells in each column, so m*m pairs
                    col_sum = (col_sum + col_diff * m * m) % MOD

        # Total sum of Manhattan distances over all unordered pairs of cells
        total_distance = (row_sum + col_sum) % MOD

        # Total sum over all arrangements = arrangements_with_pair * total_distance
        result = (arrangements_with_pair * total_distance) % MOD

        return result

