class Solution:
    def findValidPair(self, s: str) -> str:
        # Count frequency of each digit
        digit_count = {}
        for char in s:
            digit_count[char] = digit_count.get(char, 0) + 1

        # Traverse the string to find first valid adjacent pair
        for i in range(len(s) - 1):
            first_digit = s[i]
            second_digit = s[i + 1]

            # Check if digits are different
            if first_digit != second_digit:
                # Check if each digit appears exactly as many times as its value
                if digit_count[first_digit] == int(first_digit) and digit_count[second_digit] == int(second_digit):
                    return first_digit + second_digit

        return ""

class Solution:
    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        n = len(nums)
        total = 0

        for i in range(n):
            is_good = True

            # Check if element at index i is strictly greater than nums[i-k]
            if i - k >= 0:
                if nums[i] <= nums[i - k]:
                    is_good = False

            # Check if element at index i is strictly greater than nums[i+k]
            if i + k < n:
                if nums[i] <= nums[i + k]:
                    is_good = False

            if is_good:
                total += nums[i]

        return total

class Solution:
    def separateSquares(self, squares: List[List[int]]) -> float:
        from collections import defaultdict

        # Total area of all squares
        total_area = 0
        for x, y, l in squares:
            total_area += l * l

        # Binary search on y-coordinate
        left, right = 0.0, 10**9 + 1.0

        # Function to calculate area below a given y-coordinate
        def area_below(y):
            area = 0.0
            for x, y_i, l in squares:
                # Square is below y if its top edge is above y
                if y_i + l > y:
                    # Height of intersection below y
                    height = min(l, y - y_i)
                    area += height * l
            return area

        # Binary search until precision is achieved
        while right - left > 1e-5:
            mid = (left + right) / 2.0
            area_below_mid = area_below(mid)
            if area_below_mid < total_area / 2.0:
                left = mid
            else:
                right = mid

        return left

