class Solution:
    def transformArray(self, nums: List[int]) -> List[int]:
        # Replace even numbers with 0 and odd numbers with 1
        transformed = [0 if num % 2 == 0 else 1 for num in nums]
        # Sort the array in non-decreasing order
        return sorted(transformed)

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]
        if n == 2:
            return max(nums[0], nums[1])

        # Use dynamic programming with state as the current index
        # dp[i] represents the minimum cost to remove elements from index i onwards
        # We can only remove from the first three elements at each step

        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dp(i):
            if i >= n - 1:
                return 0
            if i == n - 1:
                return nums[i]
            if i == n - 2:
                return max(nums[i], nums[i+1])

            # We can remove any two of the first three elements (i, i+1, i+2)
            # and continue with the remaining elements

            # Option 1: remove nums[i] and nums[i+1]
            cost1 = max(nums[i], nums[i+1]) + dp(i+2)

            # Option 2: remove nums[i] and nums[i+2]
            cost2 = max(nums[i], nums[i+2]) + dp(i+1)

            # Option 3: remove nums[i+1] and nums[i+2]
            cost3 = max(nums[i+1], nums[i+2]) + dp(i+1)

            return min(cost1, cost2, cost3)

        return dp(0)

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]
        if n == 2:
            return max(nums[0], nums[1])

        # dp[i] represents the minimum cost to remove all elements from index i onwards
        # We'll use bottom-up DP, considering that we can only remove from first three elements

        # Base cases: when only 1 or 2 elements remain
        dp = [0] * (n + 1)

        # Base cases
        if n >= 1:
            dp[n] = 0
        if n >= 2:
            dp[n-1] = nums[n-1]
        if n >= 3:
            dp[n-2] = max(nums[n-2], nums[n-1])

        # For arrays of size >= 3, we process from left to right
        # We consider all possible pairs from first three elements at each step
        for i in range(n - 3, -1, -1):
            # Option 1: remove nums[i] and nums[i+1]
            cost1 = max(nums[i], nums[i+1]) + dp[i+2]

            # Option 2: remove nums[i] and nums[i+2]
            cost2 = max(nums[i], nums[i+2]) + dp[i+1]

            # Option 3: remove nums[i+1] and nums[i+2]
            cost3 = max(nums[i+1], nums[i+2]) + dp[i+1]

            dp[i] = min(cost1, cost2, cost3)

        return dp[0]

class Solution:
    def minCost(self, nums: List[int]) -> int:
        n = len(nums)
        if n == 1:
            return nums[0]
        if n == 2:
            return max(nums[0], nums[1])

        # dp[i] represents the minimum cost to remove all elements from index i onwards
        # We'll use bottom-up DP, considering that we can only remove from first three elements

        # Base cases: when only 1 or 2 elements remain
        dp = [0] * (n + 1)

        # Base cases
        if n >= 1:
            dp[n] = 0
        if n >= 2:
            dp[n-1] = nums[n-1]
        if n >= 3:
            dp[n-2] = max(nums[n-2], nums[n-1])

        # For arrays of size >= 3, we process from left to right
        # We consider all possible pairs from first three elements at each step
        for i in range(n - 3, -1, -1):
            # Option 1: remove nums[i] and nums[i+1]
            cost1 = max(nums[i], nums[i+1]) + dp[i+2]

            # Option 2: remove nums[i] and nums[i+2]
            cost2 = max(nums[i], nums[i+2]) + dp[i+1]

            # Option 3: remove nums[i+1] and nums[i+2]
            cost3 = max(nums[i+1], nums[i+2]) + dp[i+1]

            dp[i] = min(cost1, cost2, cost3)

        return dp[0]

class Solution:
    def reverseDegree(self, s: str) -> int:
        total = 0
        for i, char in enumerate(s):
            # Position in reversed alphabet: 'a' = 26, 'b' = 25, ..., 'z' = 1
            reversed_alphabet_pos = 26 - (ord(char) - ord('a') + 1)
            # 1-indexed position in string
            string_pos = i + 1
            total += reversed_alphabet_pos * string_pos
        return total

class Solution:
    def reverseDegree(self, s: str) -> int:
        total = 0
        for i, char in enumerate(s):
            # Position in reversed alphabet: 'a' = 26, 'b' = 25, ..., 'z' = 1
            reversed_alphabet_pos = 26 - (ord(char) - ord('a'))
            # 1-indexed position in string
            string_pos = i + 1
            total += reversed_alphabet_pos * string_pos
        return total
